insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ucad', 'Université Cheikh Anta Diop (UCAD)', 'SN', 'Dakar', 'Publique', array['droit','sante','sciences','business','education','tech'], 43, null, array['fr'], 3, 8, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Université publique historique de Dakar, avec des facultés de médecine, droit, sciences, lettres et économie. Le coût est très bas pour les bacheliers sénégalais, mais les amphithéâtres sont souvent surchargés : il faut de l''autonomie pour réussir.', array['Frais quasi nuls pour les nationaux','Large choix de filières, de la licence au doctorat','Diplômes reconnus dans toute la zone CAMES'], array['Effectifs très élevés et grèves possibles qui décalent le calendrier','Logement universitaire très demandé, places limitées'], 0, 'https://www.ucad.sn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('cesag', 'CESAG — Centre Africain d''Études Supérieures en Gestion', 'SN', 'Dakar', 'Privée', array['business','sante'], 2095, 2095, array['fr'], 3, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Institution inter-États de l''UEMOA basée à Dakar, spécialisée en gestion, audit, comptabilité, finance et management de la santé. Promotions à taille humaine et forte présence des cabinets d''audit dans les débouchés. Les frais sont nettement plus élevés qu''à l''université publique.', array['Spécialisation pointue en audit, comptabilité et finance','Réseau d''anciens dans les cabinets et banques de la sous-région','Programmes en santé publique et management de la santé'], array['Coût élevé pour un budget faible','Offre de filières concentrée sur la gestion : peu d''options hors business et santé'], 0, 'https://www.cesag.sn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ism-dakar', 'ISM — Groupe Institut Supérieur de Management', 'SN', 'Dakar', 'Privée', array['business','droit','tech','comm','ingenierie'], null, null, array['fr','en'], 2, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Groupe privé avec plusieurs écoles (management, droit, ingénierie, digital). Ambiance très active, beaucoup d''étudiants de la sous-région et des formations courtes professionnalisantes. La qualité varie selon les programmes : regarde bien la reconnaissance du diplôme visé.', array['Formations courtes (BTS) à master','Vie étudiante animée et nombreux clubs','Partenariats internationaux pour des doubles diplômes'], array['Frais élevés comparés au public','Qualité et reconnaissance inégales selon les programmes'], 0, 'https://www.groupeism.sn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ufhb', 'Université Félix Houphouët-Boigny', 'CI', 'Abidjan', 'Publique', array['droit','sante','sciences','business','education'], null, null, array['fr'], 3, 8, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Grande université publique du campus de Cocody. Très accessible financièrement pour les Ivoiriens, avec un large éventail de filières. Comme beaucoup d''universités publiques de la région, les effectifs sont importants et le calendrier peut glisser.', array['Coût très faible pour les nationaux','Grande variété de filières','Situation centrale à Abidjan, pôle économique'], array['Amphithéâtres surchargés','Peu de places en résidence universitaire'], 0, 'https://www.univ-fhb.edu.ci') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('inphb', 'Institut National Polytechnique Félix Houphouët-Boigny (INP-HB)', 'CI', 'Yamoussoukro', 'Publique', array['ingenierie','agri','business','sciences','tech'], null, null, array['fr'], 2, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Grande école publique d''ingénieurs et de techniciens, recrutée sur concours très sélectif. Campus résidentiel à Yamoussoukro, encadrement plus serré qu''à l''université. Les places sont rares et la préparation au concours demande un vrai travail en maths et sciences.', array['Diplômes d''ingénieur très recherchés par les employeurs','Campus résidentiel avec vie étudiante intense','Écoles en agronomie, mines, génie civil, commerce'], array['Concours très sélectif','Ville plus calme, moins d''opportunités de stages qu''à Abidjan'], 0, 'https://www.inphb.ci') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ug-legon', 'University of Ghana', 'GH', 'Accra (Legon)', 'Publique', array['business','sciences','sante','droit','agri','comm','education'], 249, null, array['en'], 4, 7, 'WASSCE ou diplôme équivalent avec des crédits dans les matières clés. Les candidats internationaux postulent en ligne au guichet international.', 'Plus ancienne et plus grande université du Ghana, sur un grand campus à Legon. Enseignement en anglais, licences en 4 ans. Une bonne option anglophone dans la région, avec une vie de campus riche. Les frais internationaux sont bien plus élevés que pour les Ghanéens.', array['Enseignement en anglais en Afrique de l''Ouest','Grand campus avec halls de résidence','Large éventail de disciplines'], array['Frais internationaux élevés par rapport aux nationaux','Logement sur le campus parfois insuffisant'], 0, 'https://www.ug.edu.gh') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('unilag', 'University of Lagos (UNILAG)', 'NG', 'Lagos', 'Publique', array['business','ingenierie','droit','sante','sciences','comm'], 65, null, array['en'], 4, 6, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Université fédérale au bord de la lagune, très demandée par les étudiants nigérians. Accès par l''examen UTME (JAMB) pour les nationaux. Lagos offre un marché du travail énorme, mais la ville est chère et embouteillée.', array['Situation au cœur du principal pôle économique d''Afrique de l''Ouest','Facultés reconnues en ingénierie, droit et business'], array['Concurrence forte à l''entrée','Coût de la vie élevé à Lagos'], 0, 'https://unilag.edu.ng') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('2ie', '2iE — Institut International d''Ingénierie de l''Eau et de l''Environnement', 'BF', 'Ouagadougou', 'Privée', array['ingenierie','agri','sciences'], null, null, array['fr','en'], 3, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'École d''ingénieurs internationale spécialisée dans l''eau, l''énergie, le génie civil et l''environnement. Étudiants de toute l''Afrique, accréditation internationale. Frais élevés pour la région, mais nombreuses bourses de partenaires.', array['Accréditation CTI et EUR-ACE','Spécialités très demandées : eau, énergie, BTP','Brassage panafricain'], array['Coût élevé sans bourse','Contexte sécuritaire régional à surveiller'], 0, 'https://www.2ie-edu.org') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('um5', 'Université Mohammed V de Rabat', 'MA', 'Rabat', 'Publique', array['droit','sante','sciences','ingenierie','business','education'], null, null, array['fr','ar'], 3, 8, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Grande université publique de la capitale, avec médecine, ingénierie (EMI), droit et sciences. Pas de frais de scolarité dans le public ; les étudiants étrangers passent souvent par les bourses de l''AMCI. Enseignement en français et en arabe selon les filières.', array['Pas de frais de scolarité','Bourses AMCI pour de nombreux pays africains','Écoles d''ingénieurs et faculté de médecine réputées'], array['Accès des étrangers surtout via quotas et bourses','Certaines filières en arabe : vérifie la langue d''enseignement'], 0, 'https://www.um5.ac.ma') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('um6p', 'Université Mohammed VI Polytechnique (UM6P)', 'MA', 'Ben Guerir', 'Privée', array['ingenierie','tech','agri','business','sciences'], null, null, array['en','fr'], 3, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Université à but non lucratif soutenue par le groupe OCP, avec un campus moderne à Ben Guerir. Forte orientation recherche, entrepreneuriat et data. Les frais affichés sont élevés mais l''université annonce de nombreuses bourses sur critères sociaux et de mérite.', array['Campus moderne et équipements de recherche','Programmes en anglais et en français','Bourses nombreuses'], array['Ville de Ben Guerir petite et isolée','Établissement jeune : réseau d''anciens encore limité'], 0, 'https://www.um6p.ma') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uct', 'University of Cape Town (UCT)', 'ZA', 'Le Cap', 'Publique', array['sante','business','sciences','ingenierie','droit','art'], 3409, 3717, array['en'], 3, 6, 'Équivalence du diplôme via Universities South Africa (exemption), résultats suffisants dans les matières requises, anglais certifié pour les non-anglophones.', 'Université de recherche de premier plan au pied de Table Mountain. Niveau académique élevé et reconnaissance internationale. Pour les étudiants étrangers, il faut compter des frais internationaux et un coût de vie plus élevé qu''ailleurs sur le continent.', array['Reconnaissance internationale forte','Recherche de haut niveau en santé et sciences','Cadre de vie exceptionnel'], array['Coût total élevé pour un étudiant étranger','Questions de sécurité à prendre au sérieux en ville'], 0, 'https://www.uct.ac.za') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('strathmore', 'Strathmore University', 'KE', 'Nairobi', 'Privée', array['business','tech','droit','sciences'], 2808, 2808, array['en'], 4, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Université privée de Nairobi connue pour ses programmes en commerce, finance, informatique et droit, et pour ses liens avec l''écosystème tech kényan. Encadrement exigeant et discipline académique stricte.', array['Proximité avec l''écosystème tech de Nairobi','Programmes en finance et informatique reconnus'], array['Logement sur campus limité','Cadre très strict qui ne plaît pas à tout le monde'], 0, 'https://strathmore.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ubordeaux', 'Université de Bordeaux', 'FR', 'Bordeaux', 'Publique', array['sante','sciences','droit','business','education','tech'], null, null, array['fr'], 3, 8, 'Bac français : Parcoursup. Bac étranger (hors UE) : procédure « Études en France » de Campus France dans plus de 60 pays, ou demande d''admission préalable (DAP) pour une 1ère année de licence. Niveau B2 en français demandé aux non-francophones (TCF ou DELF/DALF).', 'Université publique pluridisciplinaire, forte en santé, sciences et droit. Les étudiants hors UE peuvent payer des frais « différenciés » (environ 3 150 $ en licence), mais de nombreuses exonérations existent. Bordeaux est une ville étudiante agréable, avec un logement plus abordable qu''à Paris.', array['Diplômes nationaux reconnus en Europe','Frais très bas pour les Européens, exonérations fréquentes','Ville étudiante à taille humaine'], array['Démarches de visa et de logement longues à anticiper','Grandes promotions en première année'], 0, 'https://www.u-bordeaux.fr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('sorbonne', 'Sorbonne Université', 'FR', 'Paris', 'Publique', array['sciences','sante','art','education'], null, null, array['fr'], 3, 8, 'Bac français : Parcoursup. Bac étranger (hors UE) : procédure « Études en France » de Campus France dans plus de 60 pays, ou demande d''admission préalable (DAP) pour une 1ère année de licence. Niveau B2 en français demandé aux non-francophones (TCF ou DELF/DALF).', 'Université de recherche issue de la fusion de Paris-Sorbonne et Pierre-et-Marie-Curie : lettres, sciences et médecine. Prestige et exigence académique au cœur de Paris. Le logement à Paris est cher et difficile à trouver.', array['Reconnaissance mondiale en sciences et lettres','Frais publics français','Vie culturelle parisienne'], array['Coût de la vie très élevé à Paris','Peu d''accompagnement individuel en licence'], 0, 'https://www.sorbonne-universite.fr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('sciencespo', 'Sciences Po Paris', 'FR', 'Paris', 'Publique', array['droit','business','comm','education'], null, null, array['fr','en'], 3, 5, 'Candidature directe auprès de l''école, très sélective. Dossier académique solide, tests standardisés selon le programme (GMAT/GRE, TAGE MAGE), anglais certifié, essais et entretiens.', 'Établissement sélectif en sciences sociales, politiques publiques, droit et journalisme, avec des campus en région (Reims, Menton, Poitiers…) pour le Collège universitaire. Les frais dépendent des revenus pour les familles européennes ; hors UE, ils sont élevés, avec des bourses.', array['Réseau international exceptionnel','Année obligatoire à l''étranger en licence','Enseignement bilingue'], array['Très sélectif','Frais élevés hors UE'], 0, 'https://www.sciencespo.fr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('hec', 'HEC Paris', 'FR', 'Jouy-en-Josas', 'Privée', array['business'], null, null, array['en','fr'], 1, 3, 'Candidature directe auprès de l''école, très sélective. Dossier académique solide, tests standardisés selon le programme (GMAT/GRE, TAGE MAGE), anglais certifié, essais et entretiens.', 'Grande école de commerce de premier plan, sur un campus boisé près de Versailles. Programmes post-bac (Bachelor avec l''École polytechnique) et surtout masters et MBA. Les débouchés en conseil et finance sont excellents, mais l''investissement financier est lourd.', array['Réseau d''anciens très puissant','Débouchés en conseil, finance, entrepreneuriat','Campus résidentiel'], array['Coût total très élevé','Admission extrêmement sélective'], 0, 'https://www.hec.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uclouvain', 'UCLouvain', 'BE', 'Louvain-la-Neuve', 'Publique', array['sciences','sante','ingenierie','business','droit','education'], null, null, array['fr','en'], 3, 7, 'Diplôme de fin de secondaire reconnu équivalent par la Fédération Wallonie-Bruxelles (demande d''équivalence obligatoire pour un diplôme étranger). Certaines filières (médecine, ingénieur civil) imposent un examen d''entrée.', 'Grande université francophone de Belgique, dans une ville piétonne entièrement pensée pour les étudiants. Les frais hors UE sont d''environ 4 800 $, avec des tarifs réduits pour les ressortissants de certains pays en développement. Très bon rapport qualité-prix en Europe.', array['Excellent rapport qualité-prix','Ville étudiante unique','Tarifs réduits pour certains pays'], array['Équivalence de diplôme obligatoire, démarche longue','Examens d''entrée pour médecine et ingénieur'], 0, 'https://uclouvain.be') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('tum', 'Technische Universität München (TUM)', 'DE', 'Munich', 'Publique', array['ingenierie','tech','sciences','sante','business'], null, null, array['de','en'], 3, 5, 'Le diplôme étranger doit être reconnu comme équivalent à l''Abitur. Sinon, une année de Studienkolleg (préparation) et l''examen « Feststellungsprüfung » sont nécessaires. Niveau de langue : allemand C1 (TestDaF/DSH) ou anglais pour les programmes anglophones.', 'Université technique d''excellence. Depuis 2024, les étudiants hors UE paient des frais de scolarité (environ 4 300 à 6 500 $ par an selon le programme) ; les Européens ne paient qu''une contribution semestrielle. Munich est l''une des villes les plus chères d''Allemagne.', array['Niveau mondial en ingénierie et informatique','Liens forts avec l''industrie (BMW, Siemens…)','Nombreux masters en anglais'], array['Frais pour les non-Européens depuis 2024','Logement rare et cher à Munich','Licences surtout en allemand'], 0, 'https://www.tum.de') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('rwth', 'RWTH Aachen University', 'DE', 'Aix-la-Chapelle', 'Publique', array['ingenierie','tech','sciences'], null, null, array['de','en'], 3, 5, 'Le diplôme étranger doit être reconnu comme équivalent à l''Abitur. Sinon, une année de Studienkolleg (préparation) et l''examen « Feststellungsprüfung » sont nécessaires. Niveau de langue : allemand C1 (TestDaF/DSH) ou anglais pour les programmes anglophones.', 'Très grande université technique, sans frais de scolarité : seule une contribution semestrielle (environ 700 $ par an, avec titre de transport) est demandée, y compris aux étrangers. Exigeante, avec un fort taux d''échec en première année. La plupart des licences sont en allemand.', array['Pas de frais de scolarité','Réputation mondiale en ingénierie','Coût de la vie raisonnable'], array['Allemand indispensable en licence','Taux d''échec élevé les premières années','Compte bloqué d''environ 12 000 $ exigé pour le visa'], 0, 'https://www.rwth-aachen.de') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('unige', 'Université de Genève', 'CH', 'Genève', 'Publique', array['droit','sciences','sante','business','education'], null, null, array['fr','en'], 3, 6, 'Diplôme de fin d''études secondaires jugé équivalent à la maturité suisse, avec des exigences de notes et de matières. Certains diplômes imposent un examen complémentaire. Niveau de français B2 à C1 selon la faculté.', 'Frais de scolarité bas (environ 1 150 $ par an) même pour les étrangers, et proximité unique avec l''ONU et les organisations internationales. Mais Genève est l''une des villes les plus chères au monde : le budget de vie est le vrai défi.', array['Frais de scolarité bas','Écosystème des organisations internationales','Excellent niveau en droit, relations internationales, sciences'], array['Coût de la vie parmi les plus élevés au monde','Logement très difficile à trouver','Travail limité pour les étudiants hors UE'], 0, 'https://www.unige.ch') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('udem', 'Université de Montréal', 'CA', 'Montréal', 'Publique', array['sante','sciences','droit','education','art','tech'], 2276, 22464, array['fr'], 3, 7, 'Diplôme d''études secondaires plus une année d''études supérieures pour certains systèmes (le DEC québécois sert de référence). Dossier académique, puis Certificat d''acceptation du Québec (CAQ) et permis d''études.', 'Grande université de recherche francophone, avec HEC Montréal et Polytechnique Montréal affiliées. Les frais internationaux sont élevés (environ 22 000 $), mais des exemptions existent pour certains pays et les Français/Belges francophones paient beaucoup moins. Permis de travail après les études intéressant pour immigrer.', array['Études en français en Amérique du Nord','Voie vers le permis de travail post-diplôme','Stages coopératifs dans certains programmes'], array['Frais internationaux élevés sans exemption','Hivers rigoureux','Démarches CAQ + permis longues'], 0, 'https://www.umontreal.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ulaval', 'Université Laval', 'CA', 'Québec', 'Publique', array['sante','sciences','agri','business','droit','education'], 2276, 19779, array['fr'], 3, 6, 'Diplôme d''études secondaires plus une année d''études supérieures pour certains systèmes (le DEC québécois sert de référence). Dossier académique, puis Certificat d''acceptation du Québec (CAQ) et permis d''études.', 'Grand campus à Québec, ville sûre et moins chère que Montréal. Programme de bourses d''excellence et d''exemption des frais majorés pour les étudiants internationaux (jusqu''à environ 25 000 $). Bonne option francophone si tu vises une bourse.', array['Bourses d''exemption pour étudiants internationaux','Ville sûre, coût de la vie modéré','Campus relié par tunnels l''hiver'], array['Frais élevés sans bourse','Marché du travail plus petit qu''à Montréal'], 0, 'https://www.ulaval.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('utoronto', 'University of Toronto', 'CA', 'Toronto', 'Publique', array['sciences','tech','ingenierie','business','sante','droit','art'], 4453, 48260, array['en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Université de recherche de rang mondial. Les frais internationaux sont parmi les plus élevés du Canada, mais la bourse Lester B. Pearson couvre entièrement scolarité, livres et logement pendant 4 ans pour une poignée d''élèves exceptionnels.', array['Reconnaissance mondiale','Bourse Lester B. Pearson (complète)','Toronto, grand marché du travail'], array['Frais internationaux très élevés','Logement cher à Toronto','Grandes classes en première année'], 0, 'https://www.utoronto.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('mit', 'Massachusetts Institute of Technology (MIT)', 'US', 'Cambridge (Boston)', 'Privée', array['ingenierie','tech','sciences','business'], 66720, 66720, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Référence mondiale en sciences et ingénierie. Le prix affiché est très élevé, mais l''admission est « need-blind » pour tous, y compris les étudiants internationaux, et l''aide financière couvre l''intégralité du besoin démontré. Un dossier exceptionnel est indispensable : le taux d''admission est d''environ 4 %.', array['N°1 mondial','Aide financière couvrant 100 % du besoin','Recherche et innovation sans équivalent'], array['Taux d''admission d''environ 4 %','Rythme de travail très intense'], 0, 'https://www.mit.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('utokyo', 'Université de Tokyo', 'JP', 'Tokyo', 'Publique', array['sciences','ingenierie','tech','sante','droit'], 4308, 4308, array['en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université la plus prestigieuse du Japon. Les frais publics japonais sont modérés (environ 3 600 $ par an), et la bourse du gouvernement japonais (MEXT) peut tout couvrir. Les programmes en anglais (PEAK, masters) sont limités : une grande partie de l''enseignement reste en japonais.', array['Frais modérés pour un top mondial','Bourse MEXT complète','Recherche de pointe'], array['Peu de licences en anglais','Barrière de la langue au quotidien'], 0, 'https://www.u-tokyo.ac.jp') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('kaist', 'KAIST', 'KR', 'Daejeon', 'Publique', array['ingenierie','tech','sciences','business'], null, null, array['en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Institut scientifique et technologique de premier plan en Corée du Sud, avec un enseignement largement en anglais. Les étudiants internationaux admis reçoivent très souvent une bourse couvrant la scolarité, voire une allocation. Ambiance très studieuse, campus résidentiel.', array['Bourses fréquentes pour les internationaux','Cours largement en anglais','Dortoirs bon marché'], array['Pression académique forte','Daejeon moins animée que Séoul'], 0, 'https://www.kaist.ac.kr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('tsinghua', 'Université Tsinghua', 'CN', 'Pékin', 'Publique', array['ingenierie','tech','sciences','business'], null, 3640, array['en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université d''élite en ingénierie et sciences. Les frais internationaux restent modérés, et les bourses du gouvernement chinois (CSC) couvrent souvent tout. Les licences sont majoritairement en chinois : prévoir une année de langue, ou viser un master en anglais.', array['Excellence en ingénierie','Bourses CSC complètes','Frais modérés'], array['Chinois souvent nécessaire en licence','Accès restreint à certains services en ligne'], 0, 'https://www.tsinghua.edu.cn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('nus', 'National University of Singapore (NUS)', 'SG', 'Singapour', 'Publique', array['tech','business','ingenierie','sciences','sante','droit'], 6391, 16478, array['en'], 4, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Meilleure université d''Asie, entièrement en anglais. Avec la « Tuition Grant » du gouvernement, les frais internationaux baissent fortement, mais en échange tu t''engages à travailler 3 ans à Singapour après le diplôme. Coût de la vie élevé.', array['Top 10 mondial, tout en anglais','Hub économique asiatique','Grande sécurité'], array['Tuition Grant = engagement de 3 ans à Singapour','Admission très sélective','Vie chère'], 0, 'https://www.nus.edu.sg') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('khalifa', 'Khalifa University', 'AE', 'Abu Dhabi', 'Publique', array['ingenierie','sciences','tech','sante'], 25840, 25840, array['en'], 2, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université de recherche en sciences et ingénierie. Pour les masters et doctorats, des bourses complètes (frais, et souvent logement et allocation) sont proposées aux étudiants internationaux admis. Les places en licence pour les étrangers sont plus limitées.', array['Bourses complètes en master/doctorat','Laboratoires modernes','Environnement très international'], array['Surtout adaptée aux masters et doctorats','Climat très chaud'], 0, 'https://www.ku.ac.ae') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uopeople', 'University of the People', 'US', 'En ligne', 'En ligne', array['business','tech','sante','education'], 1800, 1800, array['en'], 2, 4, 'Admission ouverte : diplôme de fin de secondaire (ou équivalent) et niveau de langue suffisant pour suivre les cours. Aucun déménagement nécessaire.', 'Université américaine 100 % en ligne et sans frais de scolarité : tu paies seulement des frais d''évaluation par cours (environ 1 200 à 1 600 $ par an selon le rythme). Idéale si tu dois travailler en parallèle ou si tu ne peux pas partir. Il faut beaucoup d''autonomie, et la reconnaissance du diplôme varie selon les employeurs et les pays.', array['Très faible coût, bourses possibles','Compatible avec un emploi','Accessible depuis n''importe quel pays'], array['Pas de vie de campus','Reconnaissance inégale selon les pays','Demande une forte autodiscipline'], 0, 'https://www.uopeople.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uvs', 'Université Numérique Cheikh Hamidou Kane (ex-UVS)', 'SN', 'En ligne (Sénégal)', 'En ligne', array['tech','business','education','comm','sciences'], null, null, array['fr'], 3, 5, 'Admission ouverte : diplôme de fin de secondaire (ou équivalent) et niveau de langue suffisant pour suivre les cours. Aucun déménagement nécessaire.', 'Université publique sénégalaise qui enseigne à distance, avec des Espaces Numériques Ouverts (ENO) dans les régions pour se connecter et travailler. Très bon marché pour les bacheliers sénégalais. Il faut une bonne connexion et beaucoup d''autonomie.', array['Coût très faible','Étudier sans quitter sa région','Diplômes d''État'], array['Connexion internet indispensable','Peu d''interactions en présentiel'], 0, 'https://www.unchk.sn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('openclassrooms', 'OpenClassrooms', 'FR', 'En ligne', 'En ligne', array['tech','business','comm','education'], null, null, array['fr','en'], 1, 2, 'Admission ouverte : diplôme de fin de secondaire (ou équivalent) et niveau de langue suffisant pour suivre les cours. Aucun déménagement nécessaire.', 'École en ligne de formations professionnalisantes courtes (développement web, data, gestion de projet…) avec mentor individuel. En alternance, la formation peut être prise en charge par l''entreprise (en France). Sinon, compter environ 300 $ par mois.', array['Formations courtes, orientées emploi','Mentor individuel','Alternance possible'], array['Pas de vie de campus','Coût non négligeable sans alternance'], 0, 'https://openclassrooms.com') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('stanford', 'Stanford University', 'US', 'Stanford (Californie)', 'Privée', array['tech','ingenierie','business','sciences','sante','droit'], null, null, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université privée au cœur de la Silicon Valley, très forte en informatique, ingénierie et entrepreneuriat. Elle vise les élèves qui ont un dossier exceptionnel et des projets concrets. Le vrai obstacle : moins de 5 % d''admis, et le coût dépasse 90 000 $ par an sans bourse.', array['Lien direct avec les startups et les grandes entreprises tech de la Silicon Valley','Grande liberté pour choisir ses cours et changer de filière','Bourses généreuses une fois admis si la famille a peu de moyens'], array['Admission extrêmement sélective, encore plus pour les internationaux qui demandent une aide','Région parmi les plus chères au monde pour se loger'], 0, 'https://www.stanford.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('harvard', 'Harvard University', 'US', 'Cambridge (Massachusetts)', 'Privée', array['business','droit','sante','sciences','tech','education'], null, null, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'La plus ancienne université des États-Unis, avec un premier cycle (Harvard College) de culture générale avant la spécialisation. Elle convient aux élèves brillants et très engagés hors des cours. Le point d''attention : moins de 4 % d''admis, mais l''aide financière est l''une des meilleures au monde pour les familles modestes.', array['Aide financière need-blind même pour les étudiants africains','Réseau d''anciens très puissant dans tous les secteurs','Ressources énormes : bibliothèques, recherche, clubs'], array['Taux d''admission inférieur à 4 %','Coût total proche de 90 000 $ par an sans bourse et région de Boston chère'], 0, 'https://www.harvard.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('caltech', 'California Institute of Technology (Caltech)', 'US', 'Pasadena (Californie)', 'Privée', array['sciences','ingenierie','tech'], null, null, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Petit institut scientifique d''environ 1 000 étudiants en licence, centré sur la physique, les maths, la chimie et l''ingénierie. Il est fait pour les passionnés de sciences qui aiment la recherche. Attention : le rythme de travail est très intense et il n''y a presque pas de filières en business ou en sciences humaines.', array['Accès à la recherche dès la première année, avec la NASA JPL à côté','Petites classes et professeurs très accessibles','Diplôme très respecté dans les sciences et la tech'], array['Charge de travail très lourde, peu de temps libre','Choix limité hors des sciences et petite vie sociale'], 0, 'https://www.caltech.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('princeton', 'Princeton University', 'US', 'Princeton (New Jersey)', 'Privée', array['sciences','ingenierie','business','tech','droit'], null, null, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université privée très axée sur la licence, avec un suivi personnel fort et un mémoire obligatoire en dernière année. Elle convient aux élèves brillants qui aiment réfléchir en profondeur. Point d''attention : sélectivité extrême (environ 5 % d''admis) et petite ville calme, loin de la vie urbaine.', array['Aide financière sans prêt, need-blind même pour les Africains','Professeurs très présents pour les étudiants de licence','Mémoire de recherche individuel en dernière année'], array['Environ 5 % d''admis','Petite ville tranquille, peu d''animation hors campus'], 0, 'https://www.princeton.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('yale', 'Yale University', 'US', 'New Haven (Connecticut)', 'Privée', array['droit','art','sciences','sante','business'], null, null, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université privée réputée pour les sciences humaines, le droit, les arts et la politique, organisée en « colleges » résidentiels où l''on vit et mange ensemble. Elle convient aux élèves curieux, bons à l''écrit et engagés. Point d''attention : environ 5 % d''admis, et New Haven a des quartiers moins sûrs autour du campus.', array['Aide financière need-blind même pour les Africains','Vie de campus très soudée grâce aux colleges résidentiels','Très forte en droit, histoire, politique et arts'], array['Sélectivité extrême','Sécurité moyenne dans certains quartiers de New Haven'], 0, 'https://www.yale.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('columbia', 'Columbia University', 'US', 'New York (New York)', 'Privée', array['business','droit','comm','ingenierie','sciences','sante','art'], null, null, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université privée à Manhattan avec un tronc commun obligatoire (le « Core ») en philosophie, littérature et sciences. Elle convient aux élèves qui veulent la vie new-yorkaise et des stages en finance, médias ou organisations internationales. Point d''attention : c''est une des écoles les plus chères des États-Unis, dans une des villes les plus chères au monde.', array['Stages faciles d''accès à New York (finance, ONU, médias)','Tronc commun solide qui apprend à penser et écrire','Ingénierie (SEAS) et journalisme très reconnus'], array['Coût total proche de 100 000 $ par an sans bourse','Campus urbain, vie de campus moins soudée'], 0, 'https://www.columbia.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uchicago', 'University of Chicago', 'US', 'Chicago (Illinois)', 'Privée', array['business','sciences','droit','sante','tech'], null, null, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université privée très intellectuelle, célèbre pour l''économie (de nombreux prix Nobel) et un tronc commun exigeant. Elle convient aux élèves qui aiment débattre, lire beaucoup et raisonner. Point d''attention : la charge de travail est réputée lourde et les hivers de Chicago sont très froids.', array['Économie et finance parmi les meilleures au monde','Formation exigeante qui apprend à argumenter','Grande ville avec beaucoup de stages'], array['Rythme de travail intense (système en trimestres)','Hivers très froids et sécurité à surveiller autour de Hyde Park'], 0, 'https://www.uchicago.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('upenn', 'University of Pennsylvania', 'US', 'Philadelphie (Pennsylvanie)', 'Privée', array['business','sante','ingenierie','droit','sciences','tech'], null, null, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université privée de l''Ivy League connue surtout pour Wharton, sa business school accessible dès la licence. Elle convient aux élèves orientés business, finance, santé ou ingénierie qui veulent un diplôme pratique. Point d''attention : environ 5 % d''admis et un coût de près de 100 000 $ par an sans bourse.', array['Wharton : licence en business reconnue partout','Doubles diplômes possibles (business + ingénierie, etc.)','Ville moins chère que New York ou Boston'], array['Ambiance très compétitive, surtout à Wharton','Sécurité à surveiller dans certains quartiers de Philadelphie'], 0, 'https://www.upenn.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('cornell', 'Cornell University', 'US', 'Ithaca (New York)', 'Privée', array['ingenierie','agri','business','sciences','tech','sante'], 50240, 74370, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Grande université de l''Ivy League avec un choix de filières très large, y compris l''agriculture, l''hôtellerie et l''ingénierie. Elle convient aux élèves qui veulent un grand campus avec beaucoup d''options. Point d''attention : Ithaca est une petite ville isolée aux hivers rudes ; les habitants de l''État de New York paient moins dans certaines écoles, mais pas les internationaux.', array['Très large choix : ingénierie, agriculture, hôtellerie, business','Agriculture et sciences de l''alimentation de haut niveau, utiles pour l''Afrique','Grand campus avec une vie étudiante riche'], array['Ville isolée et hivers longs et froids','Aide financière limitée pour les internationaux'], 0, 'https://www.cornell.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
