insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('duke', 'Duke University', 'US', 'Durham (Caroline du Nord)', 'Privée', array['sante','business','ingenierie','sciences','droit'], 76520, 76520, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université privée du Sud des États-Unis, avec un grand campus, un esprit sportif fort et de très bons programmes en santé, économie et politiques publiques. Elle convient aux élèves qui veulent un excellent niveau et une vraie vie de campus. Point d''attention : Durham est une ville moyenne, et le coût dépasse 95 000 $ par an sans aide.', array['Vie de campus très riche et esprit d''école fort','Santé, économie et politiques publiques de haut niveau','Coût de la vie local plus bas que sur les côtes'], array['Aide limitée pour les internationaux','Ville moyenne, moins de stages sur place que dans une grande ville'], 0, 'https://www.duke.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
