insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('georgetown', 'Georgetown University', 'US', 'Washington (D.C.)', 'Privée', array['droit','business','sante','comm'], 74520, 74520, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université privée jésuite à Washington, célèbre pour les relations internationales, la diplomatie et le droit. Elle convient aux élèves qui visent la diplomatie, les organisations internationales ou la politique. Point d''attention : très peu de bourses pour les étrangers, et Washington est une ville chère.', array['Relations internationales parmi les meilleures au monde','Stages à la Banque mondiale, au FMI, dans les ambassades','Beaucoup d''étudiants internationaux'], array['Très peu d''aide financière pour les internationaux','Logement cher à Washington'], 0, 'https://www.georgetown.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('georgia-tech', 'Georgia Institute of Technology (Georgia Tech)', 'US', 'Atlanta (Géorgie)', 'Publique', array['ingenierie','tech','sciences','business'], 12134, 37326, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université publique d''ingénierie à Atlanta, parmi les meilleures du pays en génie industriel, informatique et aérospatial. Elle convient aux élèves forts en maths qui veulent un diplôme d''ingénieur reconnu pour moins cher qu''une école privée. Point d''attention : environ 35 000 $ par an pour un étranger, sans aide, et des cours réputés difficiles.', array['Ingénierie de très haut niveau à un prix plus bas que les privées','Programme d''alternance (co-op) très développé avec des entreprises','Grande ville avec une forte communauté africaine et afro-américaine'], array['Notes sévères et charge de travail lourde','Aucune aide selon les besoins pour les étrangers'], 0, 'https://www.gatech.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ut-austin', 'University of Texas at Austin', 'US', 'Austin (Texas)', 'Publique', array['ingenierie','business','tech','sciences','comm','droit'], 10858, 42554, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Immense université publique (plus de 50 000 étudiants) au cœur d''Austin, ville tech en plein essor. Elle convient aux élèves qui veulent l''ingénierie, l''informatique ou le business dans une grande ambiance étudiante. Point d''attention : entre 42 000 et 51 000 $ par an pour un étranger selon la filière, et des classes très grandes en début de cursus.', array['Austin attire beaucoup d''entreprises tech (stages, emplois)','Ingénierie, informatique et business (McCombs) très bien classés','Ambiance étudiante et sportive très forte'], array['Classes très grandes en première année','Admission dans la filière choisie difficile pour les non-Texans'], 0, 'https://www.utexas.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('purdue', 'Purdue University', 'US', 'West Lafayette (Indiana)', 'Publique', array['ingenierie','agri','tech','sciences','business'], 9992, 32104, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Grande université publique d''ingénierie et d''agriculture dans une petite ville de l''Indiana, avec des frais gelés depuis plus de dix ans. Elle convient aux élèves qui veulent un bon diplôme d''ingénieur américain à un prix raisonnable. Point d''attention : ville très calme et isolée, loin des grandes métropoles.', array['Un des meilleurs rapports qualité-prix en ingénierie aux États-Unis','Aéronautique et agronomie très reconnues','Coût de la vie bas'], array['Petite ville isolée, peu d''activités hors campus','Pas d''aide selon les besoins pour les étrangers'], 0, 'https://www.purdue.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('howard', 'Howard University', 'US', 'Washington (D.C.)', 'Privée', array['sante','business','comm','droit','art','ingenierie'], 39036, 39036, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Université privée historiquement noire de Washington, qui a formé de nombreux leaders afro-américains et africains. Elle convient aux élèves qui veulent un environnement où la culture noire est au centre, avec de bons programmes en santé, communication et business. Point d''attention : moins chère que l''Ivy League mais environ 60 000 $ par an tout compris, et le quartier demande de la prudence.', array['Communauté noire et africaine forte, on s''y sent chez soi','Réseau influent dans la politique, les médias et la santé','Frais plus bas que les grandes privées'], array['Services administratifs réputés lents','Washington est cher et certains alentours peu sûrs'], 0, 'https://howard.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ucla', 'University of California, Los Angeles (UCLA)', 'US', 'Los Angeles (Californie)', 'Publique', array['art','comm','ingenierie','sante','sciences','tech','business'], 16430, 55700, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Grande université publique de Los Angeles, très demandée, forte en cinéma, sciences, ingénierie et santé. Elle convient aux élèves qui veulent une grande université réputée et la vie californienne. Point d''attention : les non-Californiens paient environ 55 700 $ par an sans aide, et Los Angeles est très chère pour se loger.', array['Cinéma, théâtre et médias parmi les meilleurs du pays','Proche d''Hollywood et des entreprises tech de LA','Campus très vivant et climat agréable'], array['Logement très cher et souvent en chambre partagée','Grandes classes et forte concurrence pour certaines filières'], 0, 'https://www.ucla.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('mcgill', 'McGill University', 'CA', 'Montréal (Québec)', 'Publique', array['sante','sciences','ingenierie','business','droit','tech'], 2276, 23241, array['en','fr'], 3, 6, 'Diplôme d''études secondaires plus une année d''études supérieures pour certains systèmes (le DEC québécois sert de référence). Dossier académique, puis Certificat d''acceptation du Québec (CAQ) et permis d''études.', 'Grande université de recherche anglophone au cœur de Montréal, très connue en médecine, sciences et droit. Les frais varient beaucoup selon la faculté : environ 51 000 CAD/an en Arts mais près de 30 000 CAD en Sciences pour un international. L''admission est sélective et les cours sont en anglais, même si on peut rendre ses devoirs en français.', array['Réputation mondiale, diplôme reconnu partout','Montréal : ville bilingue, étudiante et moins chère que Toronto ou Vancouver','Droit de rendre ses travaux en français'], array['Frais très élevés en Arts, Gestion, Ingénierie et Droit pour un international','Admission sélective, surtout en médecine et en gestion','Hivers très froids et longs'], 0, 'https://www.mcgill.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ubc', 'University of British Columbia', 'CA', 'Vancouver (Colombie-Britannique)', 'Publique', array['sciences','ingenierie','business','sante','tech','agri'], 4527, 38750, array['en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Très grande université publique sur un campus en bord de mer à Vancouver, forte en sciences, environnement et business. En 2026-27, un international paie environ 51 500 CAD/an en Arts et plus de 66 000 CAD en Ingénierie ou Commerce. Le vrai problème : le logement à Vancouver est parmi les plus chers d''Amérique du Nord.', array['Campus immense et très vivant, nature tout autour','Très bonne réputation en recherche et en sciences','Grosse bourse selon les besoins (Karen McKellin) pour quelques élèves africains'], array['Vancouver est très cher, surtout pour se loger','Frais internationaux élevés et en hausse chaque année','Uniquement en anglais'], 0, 'https://www.ubc.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('waterloo', 'University of Waterloo', 'CA', 'Waterloo (Ontario)', 'Publique', array['tech','ingenierie','sciences','business'], 6570, 45260, array['en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Université spécialisée en tech, maths et ingénierie, célèbre pour son système coop : on alterne cours et stages payés en entreprise (souvent 4 à 6 stages). Très chère pour un international : environ 62 000 CAD/an en Maths et jusqu''à 75 000 CAD en génie logiciel. Ville calme, ambiance studieuse.', array['Stages coop payés qui aident à financer les études','Très recherché par Google, Microsoft et la Silicon Valley','Grande culture startup sur le campus'], array['Parmi les frais les plus élevés du Canada pour un international','Admission très sélective en informatique et génie','Petite ville, vie sociale plus calme'], 0, 'https://uwaterloo.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('western', 'Western University', 'CA', 'London (Ontario)', 'Publique', array['business','sante','sciences','ingenierie','droit'], 5840, 35040, array['en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Université classique avec une vraie vie de campus à l''américaine, connue pour la business school Ivey et la médecine. Un international paie environ 48 000 à 64 000 CAD/an selon le programme. London est une ville moyenne, moins chère que Toronto mais avec moins d''opportunités.', array['Vie étudiante très animée','Ivey (HBA) bien vu des recruteurs en finance et conseil','Coût de la vie raisonnable pour l''Ontario'], array['Frais internationaux élevés','Ville moyenne, peu de grandes entreprises sur place'], 0, 'https://www.uwo.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('queens', 'Queen''s University', 'CA', 'Kingston (Ontario)', 'Publique', array['business','ingenierie','sciences','sante','droit'], 5844, 41878, array['en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Université de taille moyenne au bord du lac Ontario, avec une forte tradition et un esprit de campus très soudé. En 2026-27, un international paie environ 44 800 CAD de frais de scolarité en Arts & Science et 60 000 CAD environ en Commerce ou Ingénierie. Kingston est une petite ville : agréable pour étudier, limitée pour trouver un emploi.', array['Esprit de campus et réseau d''anciens très forts','Commerce (Smith) très bien placé au Canada','Ville sûre et à taille humaine'], array['Petite ville, peu de stages sur place','Frais élevés en Commerce et Ingénierie'], 0, 'https://www.queensu.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ucalgary', 'University of Calgary', 'CA', 'Calgary (Alberta)', 'Publique', array['ingenierie','sciences','business','sante','education'], 5393, 22471, array['en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Grande université de recherche dans une ville dynamique liée à l''énergie et à la tech. Parmi les moins chères des grandes universités canadiennes pour un international : environ 30 800 CAD/an dans la plupart des facultés, 41 500 CAD en ingénierie. Attention : climat froid et sec, et Calgary dépend beaucoup du pétrole pour l''emploi.', array['Frais internationaux plus bas que Toronto ou Vancouver','Ville riche avec beaucoup d''emplois en ingénierie','Logement moins cher que Vancouver'], array['Hivers froids et longs','Économie locale dépendante du pétrole et du gaz','Moins connue à l''international que McGill ou UBC'], 0, 'https://www.ucalgary.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uottawa', 'Université d''Ottawa', 'CA', 'Ottawa (Ontario)', 'Publique', array['droit','sante','sciences','ingenierie','business','comm'], null, null, array['fr','en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Université bilingue dans la capitale du Canada, idéale pour un francophone : on peut suivre tout son programme en français. Un international paie environ 43 300 CAD/an en Arts ou Sciences sociales, mais l''exonération pour études en français ramène ce montant autour de 18 000 CAD. Ottawa est une ville administrative, moins animée que Montréal ou Toronto.', array['Études possibles en français, en Ontario','Grosse réduction des frais pour les francophones internationaux','Stages en gouvernement et organisations internationales (programme coop)'], array['Sans l''exonération, frais élevés','Hivers très froids','Campus urbain, vie de campus moins intense'], 0, 'https://www.uottawa.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('dalhousie', 'Dalhousie University', 'CA', 'Halifax (Nouvelle-Écosse)', 'Publique', array['sante','sciences','ingenierie','business','droit','agri'], null, null, array['en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Plus grande université des provinces maritimes, connue pour les sciences de la mer, la santé et le droit. Un international paie environ 33 000 à 51 500 CAD/an selon la faculté, avec un tarif garanti sur toute la durée du programme. Halifax est une ville côtière agréable, mais le marché de l''emploi est plus petit qu''en Ontario.', array['Frais garantis pour toute la durée du programme','Excellente en océanographie et sciences de la mer','Ville côtière à taille humaine'], array['Marché de l''emploi régional limité','Pénurie de logements à Halifax'], 0, 'https://www.dal.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('concordia', 'Concordia University', 'CA', 'Montréal (Québec)', 'Publique', array['art','business','ingenierie','tech','comm','sciences'], null, null, array['en'], 3, 6, 'Diplôme d''études secondaires plus une année d''études supérieures pour certains systèmes (le DEC québécois sert de référence). Dossier académique, puis Certificat d''acceptation du Québec (CAQ) et permis d''études.', 'Université anglophone du centre-ville de Montréal, connue pour les arts, le cinéma, l''ingénierie et la business school John Molson. Un international paie environ 34 800 CAD/an en Arts & Science et 42 000 CAD en gestion (2026-27). Moins sélective que McGill, mais l''enseignement est en anglais et le campus est très urbain.', array['Plus accessible que McGill pour l''admission','Forte en arts, design, cinéma et génie','Programmes coop avec stages payés'], array['Campus en pleine ville, peu d''espaces verts','Frais internationaux élevés en gestion et génie'], 0, 'https://www.concordia.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('york', 'York University', 'CA', 'Toronto (Ontario)', 'Publique', array['business','droit','art','sciences','ingenierie','comm'], 4526, 27740, array['en','fr'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Très grande université de Toronto, avec un campus bilingue (Glendon) où l''on peut étudier en français. Environ 40 000 CAD/an pour un international en Arts et Sciences, 47 000 CAD en ingénierie (2026-27). Toronto offre beaucoup d''emplois, mais le loyer y est très cher et le campus principal est loin du centre.', array['Campus Glendon bilingue pour les francophones','Toronto : plus grand marché de l''emploi du Canada','Admission plus accessible que l''Université de Toronto'], array['Loyers très chers à Toronto','Campus Keele excentré, long trajet vers le centre','Grèves du personnel déjà survenues plusieurs fois'], 0, 'https://www.yorku.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uqam', 'Université du Québec à Montréal (UQAM)', 'CA', 'Montréal (Québec)', 'Publique', array['comm','art','business','education','sciences','droit'], 2867, 21473, array['fr'], 3, 6, 'Diplôme d''études secondaires plus une année d''études supérieures pour certains systèmes (le DEC québécois sert de référence). Dossier académique, puis Certificat d''acceptation du Québec (CAQ) et permis d''études.', 'Grande université publique francophone au centre-ville de Montréal, accessible et tournée vers la pratique. Un international paie environ 29 400 CAD/an au baccalauréat, contre environ 10 500 CAD pour un Français ou un Belge. Point d''attention : réputation surtout locale, et grèves étudiantes assez fréquentes.', array['Tout en français, au cœur de Montréal','Moins chère que McGill ou Concordia pour un international','Bacs de 3 ans, entrée plus accessible'], array['Faible reconnaissance hors du Québec','Grèves étudiantes fréquentes qui peuvent perturber la session'], 0, 'https://uqam.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('sfu', 'Simon Fraser University', 'CA', 'Burnaby / Vancouver (Colombie-Britannique)', 'Publique', array['business','tech','sciences','comm','education','ingenierie'], 4831, 27657, array['en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Université publique sur une montagne à Burnaby, à côté de Vancouver, avec un programme coop solide. Un international paie environ 38 900 CAD/an (2026-27), moins qu''à UBC. Mais la vie dans la région de Vancouver reste très chère et le campus principal est isolé.', array['Moins chère qu''UBC dans la même région','Programme coop développé','Bonne en informatique et communication'], array['Logement très cher dans la région de Vancouver','Campus de Burnaby isolé et pluvieux'], 0, 'https://www.sfu.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('unimelb', 'University of Melbourne', 'AU', 'Melbourne (Victoria)', 'Publique', array['sciences','business','sante','droit','art','ingenierie'], 3127, 34558, array['en'], 3, 5, 'Candidature directe à l''université ou via un agent agréé. Diplôme de fin de lycée évalué par l''université (souvent avec une année « Foundation » pour les diplômes africains), anglais certifié (IELTS, TOEFL, PTE).', 'Université la plus prestigieuse d''Australie avec Sydney, avec un « modèle Melbourne » : licence large en 3 ans, puis spécialisation en master (médecine, droit, ingénierie). Un international paie environ 38 000 à 56 000 AUD/an en Arts selon les cours choisis. Le coût total (frais + vie à Melbourne) est très élevé et beaucoup de métiers demandent ensuite un master.', array['Réputation mondiale de premier plan','Melbourne : ville étudiante, multiculturelle et sûre','Droit de travailler pendant les études (visa étudiant)'], array['Très cher : frais + coût de la vie','Pour l''ingénierie, le droit ou la médecine, il faut ajouter un master','Loin de l''Afrique, billets d''avion chers'], 0, 'https://www.unimelb.edu.au') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('anu', 'Australian National University (ANU)', 'AU', 'Canberra (ACT)', 'Publique', array['sciences','tech','business','droit','ingenierie'], 3127, 35996, array['en'], 3, 5, 'Candidature directe à l''université ou via un agent agréé. Diplôme de fin de lycée évalué par l''université (souvent avec une année « Foundation » pour les diplômes africains), anglais certifié (IELTS, TOEFL, PTE).', 'Université de recherche nationale située à Canberra, la capitale, très forte en relations internationales, politique et sciences. Un international paie environ 51 000 AUD/an en Arts et près de 58 000 AUD en ingénierie. Canberra est calme et sûre, mais petite et peu animée comparée à Sydney ou Melbourne.', array['Excellente en relations internationales et politiques publiques','Grande vie en résidences sur le campus','Canberra moins chère que Sydney'], array['Frais internationaux élevés','Ville petite, peu d''emplois en dehors du gouvernement'], 0, 'https://www.anu.edu.au') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('usyd', 'University of Sydney', 'AU', 'Sydney (Nouvelle-Galles du Sud)', 'Publique', array['sante','droit','business','sciences','ingenierie','art'], 3127, 32472, array['en'], 3, 5, 'Candidature directe à l''université ou via un agent agréé. Diplôme de fin de lycée évalué par l''université (souvent avec une année « Foundation » pour les diplômes africains), anglais certifié (IELTS, TOEFL, PTE).', 'Plus ancienne université d''Australie, avec un campus historique et une offre très large (santé, droit, business, ingénierie). Un international paie environ 49 000 à 56 000 AUD/an en Arts, jusqu''à 60 600 AUD en ingénierie ou sciences. Sydney est l''une des villes les plus chères du monde pour se loger.', array['Réputation mondiale et réseau d''anciens énorme','Sydney : grand marché de l''emploi','Vie de campus très riche (clubs, sport)'], array['Logement parmi les plus chers au monde','Frais internationaux élevés','Très grands amphis en 1re année'], 0, 'https://www.sydney.edu.au') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('unsw', 'UNSW Sydney', 'AU', 'Sydney (Nouvelle-Galles du Sud)', 'Publique', array['ingenierie','tech','business','sciences','droit','sante'], 5280, 37290, array['en'], 3, 5, 'Candidature directe à l''université ou via un agent agréé. Diplôme de fin de lycée évalué par l''université (souvent avec une année « Foundation » pour les diplômes africains), anglais certifié (IELTS, TOEFL, PTE).', 'Grande université de Sydney très tournée vers l''ingénierie, la tech et le business, avec des liens forts avec les entreprises. Un international paie environ 47 000 AUD/an en Arts et autour de 57 000 à 61 000 AUD en Commerce, Ingénierie ou Sciences (2026). Le coût de la vie à Sydney est très élevé, à prévoir dès le départ.', array['Excellente en ingénierie et en informatique','Bons liens avec les employeurs australiens','Campus proche des plages de Sydney'], array['Sydney très chère pour se loger','Calendrier en trimestres : rythme intense'], 0, 'https://www.unsw.edu.au') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('oxford', 'University of Oxford', 'GB', 'Oxford', 'Publique', array['sciences','sante','droit','business','tech','ingenierie','art'], 13021, 49715, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'La plus ancienne université anglophone, organisée en colleges avec un enseignement en tout petits groupes (tutorials). Elle vise les élèves au dossier excellent, avec tests d''entrée et entretiens. Le vrai obstacle : environ 40 000 à 67 000 £ par an pour un étranger (selon la filière), et une admission parmi les plus sélectives du monde.', array['Cours en tout petits groupes avec des professeurs de haut niveau','Nom reconnu partout, réseau d''anciens très puissant','Licence en 3 ans seulement pour la plupart des filières'], array['Frais très élevés pour les étrangers et peu de bourses en licence','Rythme de travail très intense, trimestres courts et chargés','Candidature unique par an, date limite mi-octobre, une seule université parmi Oxford et Cambridge'], 0, 'https://www.ox.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('cambridge', 'University of Cambridge', 'GB', 'Cambridge', 'Publique', array['sciences','sante','ingenierie','tech','droit','business','art'], 13021, 38639, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Université historique organisée en colleges, très forte en sciences, maths, ingénierie et médecine. Pour un étranger, les frais vont d''environ 31 000 £ à plus de 70 000 £ par an selon la filière, auxquels s''ajoutent des frais de college (environ 10 000 à 12 000 £). Admission sur dossier, test et entretien, extrêmement sélective.', array['Excellence mondiale en sciences, maths et ingénierie','Petits groupes de travail (supervisions) chaque semaine','Diplôme qui ouvre les portes des meilleurs employeurs et masters'], array['Coût total très élevé (frais de scolarité + frais de college)','Sélection très dure, souvent avec des offres exigeant les meilleures notes','Impossible de candidater la même année à Oxford'], 0, 'https://www.cam.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('imperial', 'Imperial College London', 'GB', 'Londres', 'Publique', array['ingenierie','tech','sciences','sante','business'], 13021, 56791, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Université spécialisée en sciences, ingénierie, médecine et business, au cœur de Londres. Idéale pour un élève très fort en maths et sciences qui vise l''ingénierie ou la tech. Attention : environ 45 500 £ par an en ingénierie pour un étranger (2026-27), et Londres est l''une des villes les plus chères d''Europe.', array['Niveau mondial en ingénierie, informatique et médecine','Liens forts avec l''industrie et les startups de Londres','MEng intégré (licence + master en 4 ans)'], array['Frais et logement londonien très chers','Charge de travail lourde, ambiance très compétitive','Peu de choix hors sciences (pas de lettres ni de droit)'], 0, 'https://www.imperial.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ucl', 'University College London (UCL)', 'GB', 'Londres', 'Publique', array['sciences','sante','droit','business','tech','ingenierie','art','education'], 13021, 47082, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Grande université généraliste au centre de Londres, très internationale, forte en médecine, architecture, droit, économie et sciences. Elle convient aux bons élèves qui veulent un grand choix de filières dans une capitale. Le point d''attention : environ 39 000 £ par an pour un étranger (selon la filière) et le coût de la vie à Londres.', array['Très large choix de filières, toutes de bon niveau','Campus en plein centre de Londres, stages faciles à trouver','Frais fixes pour toute la licence pour la plupart des étrangers'], array['Londres très cher, résidences limitées','Grande université : moins d''encadrement individuel'], 0, 'https://www.ucl.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('kings-college-london', 'King''s College London', 'GB', 'Londres', 'Publique', array['sante','droit','business','sciences','tech','art','comm'], null, null, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Université de Londres reconnue pour la santé (médecine, soins infirmiers, pharmacie), le droit et les relations internationales. Elle convient aux élèves qui visent ces domaines dans une grande ville. Attention : les frais pour un étranger tournent autour de 30 000 à 37 000 £ par an selon la filière (estimation), plus le coût de Londres.', array['Très forte en santé, avec de grands hôpitaux partenaires','Excellente en relations internationales et études de guerre','Campus près de la Tamise, au centre de Londres'], array['Coût de la vie à Londres très élevé','Campus dispersés dans la ville, peu d''esprit « campus »'], 0, 'https://www.kcl.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('manchester', 'University of Manchester', 'GB', 'Manchester', 'Publique', array['ingenierie','tech','sciences','business','sante','droit','art'], null, null, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Très grande université du nord de l''Angleterre, forte en ingénierie, informatique, sciences et business. Bon choix pour un bon élève qui veut un diplôme reconnu avec un coût de la vie plus bas qu''à Londres. Point d''attention : environ 36 000 £ par an en informatique pour un étranger (2025-26), et une université très grande où il faut être autonome.', array['Coût de la vie nettement plus bas qu''à Londres','Grande ville étudiante très vivante et diverse','Bonne réputation auprès des employeurs britanniques'], array['Frais élevés pour les étrangers','Classes de licence souvent très nombreuses'], 0, 'https://www.manchester.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('edinburgh', 'University of Edinburgh', 'GB', 'Édimbourg (Écosse)', 'Publique', array['tech','sciences','sante','droit','business','art','education'], null, null, array['en'], 4, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Grande université écossaise historique, très forte en informatique et IA, médecine, sciences et lettres. Les licences durent 4 ans en Écosse, ce qui augmente le coût total. Pour un étranger, compter environ 30 000 à 37 000 £ par an hors médecine (estimation) ; les étudiants écossais ne paient pas de frais, ceux du reste du Royaume-Uni environ 9 800 £.', array['Référence en informatique et intelligence artificielle','Ville magnifique, très étudiante et plus sûre que les grandes capitales','Licence de 4 ans plus large et flexible'], array['4 ans de frais au lieu de 3 en Angleterre','Logement rare et cher, surtout en août (festival)'], 0, 'https://www.ed.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('bristol', 'University of Bristol', 'GB', 'Bristol', 'Publique', array['ingenierie','tech','sciences','droit','business','sante','art'], null, null, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Université réputée du sud-ouest de l''Angleterre, forte en ingénierie, sciences, droit et économie. Bon équilibre entre niveau académique et qualité de vie. Pour un étranger, les frais 2026-27 vont de 25 500 £ (droit, langues) à 33 400 £ (informatique), plus pour la médecine ; la ville est devenue chère pour se loger.', array['Très bonne réputation auprès des employeurs britanniques','Ville agréable, plus petite et plus calme que Londres','Frais plus bas que les universités londoniennes'], array['Loyers élevés et logements étudiants difficiles à trouver','Moins connue hors du Royaume-Uni qu''Oxford ou Imperial'], 0, 'https://www.bristol.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('glasgow', 'University of Glasgow', 'GB', 'Glasgow (Écosse)', 'Publique', array['sciences','sante','ingenierie','droit','business','art','education'], null, null, array['en'], 4, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Une des plus anciennes universités du monde anglophone, dans la plus grande ville d''Écosse, forte en médecine, ingénierie et sciences. Pour un étranger en 2026-27 : 27 720 £ par an en lettres et sciences sociales, 33 210 £ en sciences et ingénierie, sur 4 ans. Les bourses de réduction de frais aident, et le coût de la vie est plutôt raisonnable pour le Royaume-Uni.', array['Réductions de frais importantes pour les étudiants internationaux','Coût de la vie plus bas qu''à Londres ou Édimbourg','Campus historique et vie étudiante très active'], array['Licence en 4 ans, donc une année de frais en plus','Climat pluvieux et gris une grande partie de l''année'], 0, 'https://www.gla.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('warwick', 'University of Warwick', 'GB', 'Coventry', 'Publique', array['business','sciences','tech','ingenierie','droit','art'], null, null, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Université moderne sur un grand campus vert près de Coventry, très forte en économie, maths, business et informatique. Elle convient aux élèves solides en maths qui visent la finance ou la tech. Pour un étranger en 2026-27 : 27 870 £ par an en lettres et droit, 35 530 £ en sciences, informatique et ingénierie ; Coventry est moins animée que Londres.', array['Excellente en économie, maths et business (Warwick Business School)','Vrai campus où tout est sur place','Très recherchée par les banques et cabinets de conseil'], array['Campus un peu isolé, ville de Coventry peu attractive','Frais élevés en sciences pour les étrangers'], 0, 'https://warwick.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('birmingham', 'University of Birmingham', 'GB', 'Birmingham', 'Publique', array['ingenierie','sciences','sante','business','droit','tech','education','art'], null, null, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Grande université sur un vrai campus dans la deuxième ville d''Angleterre, forte en ingénierie, sciences, santé et business. Bon compromis entre réputation et coût de la vie. Pour un étranger, compter environ 25 000 à 33 000 £ par an selon la filière (estimation), plus pour la médecine.', array['Vrai campus avec beaucoup d''activités et de sport','Coût de la vie raisonnable pour une grande ville','Large choix de filières, bonne reconnaissance au Royaume-Uni'], array['Moins prestigieuse à l''international que les universités du top 10','Frais quand même élevés pour un budget africain'], 0, 'https://www.birmingham.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('leeds', 'University of Leeds', 'GB', 'Leeds', 'Publique', array['business','ingenierie','sciences','sante','comm','art','droit','education'], null, null, array['en'], 3, 8, 'Candidature de licence via UCAS (5 choix maximum). Ton diplôme de fin de lycée doit être jugé équivalent : beaucoup d''universités demandent une année de « Foundation » ou d''excellents résultats au bac. Anglais certifié (IELTS Academic ou équivalent) pour les non-anglophones.', 'Grande université du nord de l''Angleterre, avec un campus près du centre-ville et une très grosse vie étudiante. Forte en business, ingénierie, communication et langues. Pour un étranger, compter environ 26 000 à 35 000 £ par an selon la filière (estimation, frais 2026-27 parfois encore « à confirmer »).', array['Ville très étudiante et moins chère que le sud de l''Angleterre','Bonne business school et forte en communication','Large choix de filières avec année en entreprise possible'], array['Moins de prestige international que les universités londoniennes du top','Grande université : il faut être autonome'], 0, 'https://www.leeds.ac.uk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('psl', 'Université PSL (Paris Sciences & Lettres)', 'FR', 'Paris', 'Publique', array['sciences','ingenierie','business','art','sante','tech'], null, null, array['fr','en'], 3, 8, 'Bac français : Parcoursup. Bac étranger (hors UE) : procédure « Études en France » de Campus France dans plus de 60 pays, ou demande d''admission préalable (DAP) pour une 1ère année de licence. Niveau B2 en français demandé aux non-francophones (TCF ou DELF/DALF).', 'Regroupement de grandes écoles et instituts parisiens (ENS, Dauphine, Mines Paris, Chimie ParisTech, Institut Curie…). En licence, l''offre est petite et très sélective (CPES, licences de Dauphine). En théorie 178 € par an pour un Européen et environ 2 900 € pour un non-Européen (frais différenciés), mais certaines composantes appliquent leurs propres tarifs ; le vrai coût, c''est le logement à Paris.', array['Niveau scientifique et académique parmi les meilleurs de France','Frais de scolarité très bas comparés au Royaume-Uni','Petites promotions, encadrement proche'], array['Peu de places en licence, sélection très forte (Parcoursup ou Études en France)','Logement à Paris cher et difficile à trouver','Université éclatée en plusieurs écoles, peu de vie de campus commune'], 0, 'https://psl.eu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ip-paris', 'Institut Polytechnique de Paris', 'FR', 'Palaiseau (près de Paris)', 'Publique', array['ingenierie','tech','sciences','business'], 286, 4846, array['fr','en'], 2, 5, 'Bac français : Parcoursup. Bac étranger (hors UE) : procédure « Études en France » de Campus France dans plus de 60 pays, ou demande d''admission préalable (DAP) pour une 1ère année de licence. Niveau B2 en français demandé aux non-francophones (TCF ou DELF/DALF).', 'Regroupement de cinq écoles d''ingénieurs (Polytechnique, ENSTA, ENSAE, Télécom Paris, Télécom SudParis) sur le plateau de Saclay. Son programme principal est le master (2 ans), surtout en anglais ; en 2026-27, 255 € pour un Européen et 4 327 € pour un non-Européen en parcours national (plus en parcours international). C''est une option après une licence, pas après le bac.', array['Masters d''ingénierie, IA et data de très haut niveau','Frais bas comparés aux écoles anglo-saxonnes','Liens forts avec les grandes entreprises et la recherche'], array['Pas d''entrée directe après le bac (sauf Bachelor de Polytechnique)','Campus de Palaiseau excentré, loin de la vie parisienne'], 0, 'https://www.ip-paris.fr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('paris-saclay', 'Université Paris-Saclay', 'FR', 'Orsay / Saclay (près de Paris)', 'Publique', array['sciences','sante','ingenierie','tech','droit','business','education'], 199, 199, array['fr','en'], 3, 8, 'Bac français : Parcoursup. Bac étranger (hors UE) : procédure « Études en France » de Campus France dans plus de 60 pays, ou demande d''admission préalable (DAP) pour une 1ère année de licence. Niveau B2 en français demandé aux non-francophones (TCF ou DELF/DALF).', 'Très grande université publique au sud de Paris, réputée pour les maths, la physique et les sciences. Les licences coûtent 178 € par an pour un Européen ; un non-Européen paie en principe environ 2 900 €, souvent réduits grâce à l''exonération partielle de l''université. Point d''attention : campus étalés et parfois mal desservis, et une licence qui demande beaucoup d''autonomie.', array['Excellence mondiale en mathématiques et physique','Frais très bas, même pour les non-Européens','Logement moins cher qu''à Paris intra-muros'], array['Campus dispersés et transports parfois longs','Grands amphis en licence, peu d''encadrement','Démarches longues pour les non-Européens (Études en France, visa)'], 0, 'https://www.universite-paris-saclay.fr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('polytechnique', 'École Polytechnique', 'FR', 'Palaiseau (près de Paris)', 'Publique', array['ingenierie','sciences','tech','business'], 0, 7840, array['en','fr'], 3, 5, 'Candidature directe auprès de l''école, très sélective. Dossier académique solide, tests standardisés selon le programme (GMAT/GRE, TAGE MAGE), anglais certifié, essais et entretiens.', 'La plus prestigieuse école d''ingénieurs française. Pour un élève étranger après le bac, la porte d''entrée est le Bachelor of Science (3 ans, en anglais) : 15 900 € par an pour un Européen et 19 600 € pour un non-Européen. Le cycle ingénieur classique passe par les concours après deux ans de classe prépa, extrêmement sélectifs.', array['Prestige énorme en France et réseau d''anciens très puissant','Bachelor en anglais, très fort en maths, physique, informatique, économie','Grand campus avec logement et sport sur place'], array['Bachelor payant et cher pour une école publique française','Niveau en maths exigé très élevé','Campus isolé, loin du centre de Paris'], 0, 'https://www.polytechnique.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('essec', 'ESSEC Business School', 'FR', 'Cergy (près de Paris)', 'Privée', array['business'], null, null, array['en','fr'], 4, 5, 'Candidature directe auprès de l''école, très sélective. Dossier académique solide, tests standardisés selon le programme (GMAT/GRE, TAGE MAGE), anglais certifié, essais et entretiens.', 'Une des trois plus grandes écoles de commerce françaises. Après le bac, l''entrée se fait par le Global BBA (4 ans), en anglais ou en français, avec des campus à Cergy, Singapour et Rabat. Compter environ 17 000 à 19 000 € par an (estimation), et la sélection est forte ; le campus de Rabat est une option moins chère pour un étudiant africain.', array['Marque très reconnue par les employeurs en France et à l''étranger','Campus au Maroc (Rabat) avec bourse dédiée aux Africains','Beaucoup de stages et d''échanges à l''étranger'], array['Frais élevés sur 4 ans','Cergy est loin du centre de Paris (environ 40 min en RER)'], 0, 'https://www.essec.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('edhec', 'EDHEC Business School', 'FR', 'Lille / Nice', 'Privée', array['business'], 17808, 17808, array['en','fr'], 4, 5, 'Candidature directe auprès de l''école, très sélective. Dossier académique solide, tests standardisés selon le programme (GMAT/GRE, TAGE MAGE), anglais certifié, essais et entretiens.', 'Grande école de commerce française, très forte en finance, avec des campus à Lille et Nice. Après le bac, l''entrée se fait par l''International BBA (4 ans) : 15 900 € par an en parcours Business Management et 23 900 € en parcours Global Business (2026). Pas de tarif réduit pour les non-Européens, mais des bourses qui réduisent la facture.', array['Excellente réputation en finance','Bourses automatiques au mérite pour les internationaux','Campus à Lille et Nice, villes moins chères que Paris'], array['Coût total élevé sur 4 ans, surtout en Global Business','Moins connue hors d''Europe qu''HEC ou l''ESSEC'], 0, 'https://www.edhec.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('lmu-munich', 'Ludwig-Maximilians-Universität München (LMU Munich)', 'DE', 'Munich', 'Publique', array['sante','sciences','droit','business','art','education'], 217, 217, array['de','en'], 3, 5, 'Le diplôme étranger doit être reconnu comme équivalent à l''Abitur. Sinon, une année de Studienkolleg (préparation) et l''examen « Feststellungsprüfung » sont nécessaires. Niveau de langue : allemand C1 (TestDaF/DSH) ou anglais pour les programmes anglophones.', 'Grande université publique de recherche au cœur de Munich, sans frais de scolarité : on paie seulement une contribution d''environ 100 € par semestre. Presque toutes les licences sont en allemand, il faut donc un niveau C1. Le vrai problème, c''est Munich : la ville la plus chère d''Allemagne pour se loger.', array['Pas de frais de scolarité, même pour les étrangers','Diplôme très reconnu en Europe et dans le monde','Munich : économie forte, beaucoup de stages et d''emplois'], array['Licences presque toutes en allemand (C1 exigé)','Logement très difficile à trouver et cher à Munich','Avec un bac africain, une année de Studienkolleg est souvent exigée avant la licence'], 0, 'https://www.lmu.de') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('heidelberg', 'Heidelberg University (Ruprecht-Karls-Universität Heidelberg)', 'DE', 'Heidelberg', 'Publique', array['sante','sciences','droit','art'], 426, 3786, array['de','en'], 3, 5, 'Le diplôme étranger doit être reconnu comme équivalent à l''Abitur. Sinon, une année de Studienkolleg (préparation) et l''examen « Feststellungsprüfung » sont nécessaires. Niveau de langue : allemand C1 (TestDaF/DSH) ou anglais pour les programmes anglophones.', 'La plus ancienne université d''Allemagne, très forte en médecine et en sciences de la vie, dans une petite ville étudiante. Comme elle est dans le Bade-Wurtemberg, les étudiants hors UE paient 1 500 € par semestre en plus de la contribution habituelle. Les licences sont en allemand.', array['Excellente réputation en médecine, biologie et physique','Petite ville étudiante, plus calme et moins chère que Munich','Frais restant bas comparés au Royaume-Uni ou aux Pays-Bas'], array['1 500 € par semestre pour les étudiants hors UE','Licences en allemand ; Studienkolleg souvent nécessaire avec un bac africain','Ville petite : moins d''emplois étudiants qu''à Berlin ou Munich'], 0, 'https://www.uni-heidelberg.de') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('fu-berlin', 'Freie Universität Berlin', 'DE', 'Berlin', 'Publique', array['droit','sciences','art','business','comm','sante'], 844, 844, array['de','en'], 3, 5, 'Le diplôme étranger doit être reconnu comme équivalent à l''Abitur. Sinon, une année de Studienkolleg (préparation) et l''examen « Feststellungsprüfung » sont nécessaires. Niveau de langue : allemand C1 (TestDaF/DSH) ou anglais pour les programmes anglophones.', 'Grande université publique de Berlin, forte en sciences politiques, sciences humaines et sciences. Pas de frais de scolarité : environ 370 € par semestre, transport en commun inclus. Les licences sont en allemand et le logement à Berlin est devenu très difficile à trouver.', array['Gratuit (seulement la contribution semestrielle avec ticket de transport)','Berlin : ville internationale, startups, beaucoup de petits boulots','Très bon réseau international et beaucoup d''échanges'], array['Licences en allemand ; Studienkolleg souvent exigé avec un bac africain','Crise du logement à Berlin : chercher des mois à l''avance'], 0, 'https://www.fu-berlin.de') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('hu-berlin', 'Humboldt-Universität zu Berlin', 'DE', 'Berlin', 'Publique', array['sciences','art','droit','education','agri','sante'], null, null, array['de','en'], 3, 5, 'Le diplôme étranger doit être reconnu comme équivalent à l''Abitur. Sinon, une année de Studienkolleg (préparation) et l''examen « Feststellungsprüfung » sont nécessaires. Niveau de langue : allemand C1 (TestDaF/DSH) ou anglais pour les programmes anglophones.', 'Université historique en plein centre de Berlin, réputée en sciences humaines, sciences sociales et sciences. Pas de frais de scolarité, seulement une contribution d''environ 350-380 € par semestre avec le transport. Comme partout en Allemagne, les licences sont en allemand et se loger à Berlin est difficile.', array['Gratuit, avec ticket de transport inclus dans la contribution','Campus en plein centre de Berlin','Médecine via la Charité, hôpital universitaire très réputé'], array['Licences en allemand ; Studienkolleg souvent exigé avec un bac africain','Logement rare et de plus en plus cher à Berlin'], 0, 'https://www.hu-berlin.de') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ku-leuven', 'KU Leuven', 'BE', 'Louvain (Leuven)', 'Publique', array['sante','ingenierie','business','droit','sciences','tech'], null, null, array['nl','en'], 3, 5, 'Diplôme de fin de secondaire reconnu équivalent par la Fédération Wallonie-Bruxelles (demande d''équivalence obligatoire pour un diplôme étranger). Certaines filières (médecine, ingénieur civil) imposent un examen d''entrée.', 'La plus grande et la plus réputée des universités belges, dans une ville 100 % étudiante. Les frais restent modérés, mais la majorité des licences sont en néerlandais : en anglais, le choix est limité (ingénieur, business, philosophie…). Les frais hors UE varient selon le programme, à vérifier avant de postuler.', array['Très forte en recherche, médecine et ingénierie','Frais bien plus bas qu''aux Pays-Bas ou au Royaume-Uni','Vie étudiante très animée à Louvain'], array['La plupart des licences sont en néerlandais','Taux d''échec élevé en première année'], 0, 'https://www.kuleuven.be') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ulb', 'Université libre de Bruxelles (ULB)', 'BE', 'Bruxelles', 'Publique', array['sante','droit','business','sciences','ingenierie','comm'], 419, 1337, array['fr','en'], 3, 5, 'Diplôme de fin de secondaire reconnu équivalent par la Fédération Wallonie-Bruxelles (demande d''équivalence obligatoire pour un diplôme étranger). Certaines filières (médecine, ingénieur civil) imposent un examen d''entrée.', 'Grande université francophone de Bruxelles, avec la Solvay Brussels School pour la gestion et une forte faculté de médecine. Le tarif hors UE est de 5 369 € par an, mais tombe à 1 194 € pour les pays exemptés (à vérifier pour ton pays). Attention : beaucoup d''échecs en première année et logement de plus en plus cher à Bruxelles.', array['Enseignement en français, idéal pour les francophones','Frais réduits pour beaucoup de pays africains','Bruxelles : institutions européennes, ONG, stages internationaux'], array['Taux d''échec élevé en première année (bachelier)','Médecine et sciences dentaires soumises à un concours d''entrée'], 0, 'https://www.ulb.be') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('vub', 'Vrije Universiteit Brussel (VUB)', 'BE', 'Bruxelles', 'Publique', array['ingenierie','sante','droit','business','comm','sciences'], 1296, 1296, array['nl','en'], 3, 5, 'Diplôme de fin de secondaire reconnu équivalent par la Fédération Wallonie-Bruxelles (demande d''équivalence obligatoire pour un diplôme étranger). Certaines filières (médecine, ingénieur civil) imposent un examen d''entrée.', 'Université néerlandophone de Bruxelles, plus petite que l''ULB, avec quelques licences en anglais (sciences sociales, économie). Pour un étudiant hors UE, compter environ 5 300 € par an en sciences sociales. Hors programmes anglais, il faut parler néerlandais.', array['Classes plus petites, encadrement plus proche','Licences en anglais à prix modéré pour l''Europe','Bruxelles : institutions européennes et ONG à proximité'], array['Peu de licences en anglais, le reste est en néerlandais','Moins connue à l''international que KU Leuven ou l''ULB'], 0, 'https://www.vub.be') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('eth-zurich', 'ETH Zurich', 'CH', 'Zurich', 'Publique', array['ingenierie','tech','sciences','agri'], null, null, array['de','en'], 3, 5, 'Diplôme de fin d''études secondaires jugé équivalent à la maturité suisse, avec des exigences de notes et de matières. Certains diplômes imposent un examen complémentaire. Niveau de français B2 à C1 selon la faculté.', 'Une des meilleures écoles d''ingénieurs et de sciences au monde, publique et peu chère en frais. Depuis 2025, les étrangers paient le triple (2 190 CHF par semestre). Mais la licence est en allemand, très exigeante, et Zurich est une des villes les plus chères du monde.', array['Niveau mondial en ingénierie, informatique et sciences','Frais de scolarité bas pour ce niveau, même triplés','Diplôme ouvrant les portes des meilleures entreprises et labos'], array['Licence en allemand ; examen d''entrée souvent exigé avec un bac africain','Coût de la vie très élevé à Zurich (plus de 2 000 $ par mois)','Première année très sélective, beaucoup d''échecs'], 0, 'https://ethz.ch') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('epfl', 'École polytechnique fédérale de Lausanne (EPFL)', 'CH', 'Lausanne', 'Publique', array['ingenierie','tech','sciences','sante'], null, null, array['fr','en'], 3, 5, 'Diplôme de fin d''études secondaires jugé équivalent à la maturité suisse, avec des exigences de notes et de matières. Certains diplômes imposent un examen complémentaire. Niveau de français B2 à C1 selon la faculté.', 'Grande école d''ingénieurs fédérale, très réputée, avec une licence enseignée surtout en français. Depuis 2025, les étrangers paient 2 240 CHF par semestre et l''EPFL limite le nombre d''admis étrangers. Avec un bac non suisse, il faut d''excellentes notes, sinon passer par une année préparatoire (CMS).', array['Licence en français, niveau mondial en ingénierie','Campus moderne au bord du lac, beaucoup de startups','Frais bas pour ce niveau d''école'], array['Première année très dure, taux d''échec élevé','Places limitées pour les étrangers depuis 2025','Lausanne très chère (logement surtout)'], 0, 'https://www.epfl.ch') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('unil', 'Université de Lausanne (UNIL)', 'CH', 'Lausanne', 'Publique', array['sante','droit','business','sciences','comm'], null, null, array['fr','en'], 3, 5, 'Diplôme de fin d''études secondaires jugé équivalent à la maturité suisse, avec des exigences de notes et de matières. Certains diplômes imposent un examen complémentaire. Niveau de français B2 à C1 selon la faculté.', 'Université cantonale francophone, sur le même campus que l''EPFL, connue pour HEC Lausanne, le droit, la médecine et la science forensique. Les frais restent faibles (environ 580 CHF par semestre, à vérifier car ils peuvent évoluer pour les étrangers). Le vrai obstacle, c''est le coût de la vie à Lausanne et, selon ton bac, un examen d''admission.', array['Études en français, frais de scolarité bas','Campus vert au bord du lac, partagé avec l''EPFL','Formation unique en science forensique (police scientifique)'], array['Coût de la vie très élevé en Suisse','Avec certains bacs africains, un examen d''admission (ECUS) est demandé'], 0, 'https://www.unil.ch') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('tu-delft', 'Delft University of Technology (TU Delft)', 'NL', 'Delft', 'Publique', array['ingenierie','tech','sciences','art'], null, null, array['en','nl'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Une des meilleures universités techniques d''Europe, avec plusieurs licences en anglais (aérospatial, informatique, nanobiologie). Le gros point noir : environ 17 300 € par an pour un étudiant hors UE, et une crise du logement étudiant aux Pays-Bas. Les places sont limitées (numerus fixus) dans les filières populaires.', array['Niveau mondial en ingénierie, surtout aérospatial et génie civil','Licences en anglais','Liens forts avec l''industrie et vie associative riche'], array['Frais élevés pour les étudiants hors UE (environ 17 300 €/an)','Logement très difficile à trouver','Sélection (numerus fixus) et règle d''élimination en première année'], 0, 'https://www.tudelft.nl') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('leiden', 'Leiden University', 'NL', 'Leyde (Leiden) et La Haye', 'Publique', array['droit','sciences','sante','art'], null, null, array['en','nl'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'La plus ancienne université des Pays-Bas, forte en droit, relations internationales et sciences, avec un campus à La Haye (ville des tribunaux internationaux). Plusieurs licences en anglais, mais environ 14 700 € par an pour un étudiant hors UE. Logement rare.', array['Très bonne réputation en droit et relations internationales','Campus de La Haye : ONU, Cour pénale internationale, ambassades','Plusieurs licences en anglais'], array['Frais hors UE élevés (environ 14 700 €/an)','Crise du logement aux Pays-Bas'], 0, 'https://www.universiteitleiden.nl') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('utrecht', 'Utrecht University', 'NL', 'Utrecht', 'Publique', array['sciences','sante','droit','education','art','business'], null, null, array['nl','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Grande université généraliste au centre des Pays-Bas, forte en sciences, santé et durabilité. Les licences sont surtout en néerlandais, avec une offre limitée en anglais (dont University College Utrecht). Pour un hors UE, compter autour de 18 000-19 000 € par an selon le programme.', array['Bonne réputation en sciences, vétérinaire et développement durable','Ville étudiante centrale, bien reliée à Amsterdam','University College : petites classes en anglais'], array['Frais hors UE très élevés (environ 18 700 €/an)','Peu de licences en anglais ; logement rare'], 0, 'https://www.uu.nl') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uva', 'University of Amsterdam (UvA)', 'NL', 'Amsterdam', 'Publique', array['business','comm','droit','sciences','art','sante'], null, null, array['nl','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Grande université en plein Amsterdam, avec beaucoup de licences en anglais (économie, psychologie, communication). Pour un étudiant hors UE, les frais vont de 13 900 € à 21 800 € par an selon la faculté. Amsterdam est aussi la ville la plus chère des Pays-Bas pour se loger.', array['Large choix de licences en anglais','Référence mondiale en communication','Amsterdam : capitale internationale, beaucoup de stages'], array['Frais hors UE très élevés (13 900 à 21 800 €/an)','Logement extrêmement rare et cher à Amsterdam'], 0, 'https://www.uva.nl') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uio-oslo', 'University of Oslo (UiO)', 'NO', 'Oslo', 'Publique', array['sciences','droit','sante','art','education'], null, null, array['no','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'La plus grande et la plus ancienne université de Norvège. Depuis 2023, les étudiants hors UE paient des frais de scolarité (estimés autour de 150 000 NOK par an, à vérifier selon le programme). Presque toutes les licences sont en norvégien, et Oslo est une ville très chère.', array['Bonne réputation en recherche, droit et sciences','Pays très sûr avec une bonne qualité de vie','Gratuit pour les étudiants européens'], array['Licences presque toutes en norvégien','Frais pour les hors UE depuis 2023 + coût de la vie très élevé'], 0, 'https://www.uio.no') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('copenhagen', 'University of Copenhagen (Københavns Universitet)', 'DK', 'Copenhague', 'Publique', array['sante','sciences','droit','agri','business','art'], null, null, array['da','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Plus grande université du Danemark, très forte en santé, pharmacie et sciences. Gratuite pour les Européens, mais payante pour les hors UE (estimée entre 10 000 et 17 000 € par an). Le vrai blocage : les licences sont presque toutes en danois.', array['Excellente en santé, pharmacie et sciences de la vie','Gratuite pour les Européens','Copenhague : ville sûre, cyclable, très bonne qualité de vie'], array['Licences presque toutes en danois','Copenhague très chère, logement rare'], 0, 'https://www.ku.dk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('lund', 'Lund University', 'SE', 'Lund', 'Publique', array['ingenierie','business','droit','sciences','sante'], 0, 11875, array['sv','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Grande université suédoise dans une petite ville étudiante, avec une vie associative très riche (les « nations »). Quelques licences en anglais, comme International Business (environ 130 000 SEK par an pour un hors UE). La plupart des licences restent en suédois.', array['Vie étudiante très riche (nations, associations)','Bourse Global Scholarship possible dès la licence','Coût de la vie plus raisonnable que Stockholm ou Copenhague'], array['Peu de licences en anglais','Frais hors UE élevés (environ 12 000 $ par an)'], 0, 'https://www.lunduniversity.lu.se') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('helsinki', 'University of Helsinki', 'FI', 'Helsinki', 'Publique', array['sciences','sante','education','droit','agri'], 0, 0, array['fi','sv','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Plus grande université de Finlande, très forte en sciences et en éducation. Seulement quelques licences en anglais, à 13 000 € par an pour un hors UE, sans exonération possible. Hivers longs et sombres, et le finnois est presque indispensable pour travailler ensuite.', array['Excellente en sciences et en éducation','Frais fixes pendant toute la licence','Pays très sûr et bien organisé'], array['Peu de licences en anglais, aucune bourse d''exonération en licence','Marché du travail difficile sans parler finnois'], 0, 'https://www.helsinki.fi') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('aalto', 'Aalto University', 'FI', 'Espoo (Helsinki)', 'Publique', array['ingenierie','tech','business','art'], 0, 13440, array['fi','sv','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Université récente née de la fusion d''écoles d''ingénieurs, de commerce et de design, connue pour son esprit startup (Slush). Quelques licences en anglais, à 12 000 € par an (15 000 € en art et design) pour un hors UE. Places très limitées et hivers difficiles.', array['Culture startup très forte (Aalto Entrepreneurship Society, Slush)','Mélange unique tech, business et design','Campus moderne avec beaucoup de projets pratiques'], array['Très peu de places en licence anglophone, sélection dure','Finnois souvent nécessaire pour trouver un emploi local'], 0, 'https://www.aalto.fi') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uam-madrid', 'Universidad Autónoma de Madrid', 'ES', 'Madrid', 'Publique', array['sciences','sante','droit','business','education','tech'], 1137, 7642, array['es','en'], 4, 6, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Grande université publique de Madrid, solide en sciences, médecine, droit et économie. Les Espagnols paient environ 1 200 € par an, mais un étudiant africain hors UE paie environ 6 à 8 fois plus par crédit. Presque tous les cours de licence sont en espagnol : il faut un vrai niveau B2 et faire reconnaître ton bac (UNEDasiss).', array['Très bon niveau en sciences, médecine et droit','Frais bien plus bas qu''une école privée, même au tarif étranger','Grand campus vert à Cantoblanco, relié en train au centre de Madrid'], array['Tarif hors UE nettement plus cher que pour les Européens','Cours de licence presque tous en espagnol','Campus éloigné du centre, trajets quotidiens'], 0, 'https://www.uam.es') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('univ-barcelona', 'Universitat de Barcelona', 'ES', 'Barcelone', 'Publique', array['sante','sciences','droit','business','art','education','comm'], 1188, 1188, array['es','en'], 4, 6, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'La plus grande université publique de Catalogne, très forte en médecine, sciences et sciences humaines. En licence, le prix du crédit est le même pour tous (environ 1 100 € par an) : c''est très abordable. Mais les cours sont en catalan et en espagnol, et le logement à Barcelone est cher.', array['Frais de licence très bas, même pour les étrangers','Excellente réputation en recherche, surtout en médecine','Ville dynamique avec beaucoup de stages et d''entreprises'], array['Beaucoup de cours en catalan, en plus de l''espagnol','Loyers très élevés à Barcelone','Facultés dispersées dans la ville, peu de vie de campus'], 0, 'https://www.ub.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('iese', 'IESE Business School', 'ES', 'Barcelone / Madrid', 'Privée', array['business'], 95200, 95200, array['en','es'], 2, 2, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'École de commerce de l''Université de Navarre, qui ne fait que des MBA et des formations pour cadres : pas de licence. Le MBA plein temps dure environ 2 ans et coûte environ 117 000 € au total. C''est pour quelqu''un qui a déjà 3 à 5 ans d''expérience pro, pas pour un lycéen.', array['MBA reconnu mondialement, réseau d''anciens très puissant','Méthode des cas : on apprend en résolvant de vrais problèmes d''entreprise','Très bons débouchés en conseil et finance en Europe'], array['Très cher : environ 117 000 € de frais pour le MBA','Inaccessible après le bac : il faut plusieurs années d''expérience','Sélection très dure (GMAT/GRE, entretiens)'], 0, 'https://www.iese.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ie-university', 'IE University', 'ES', 'Madrid / Ségovie', 'Privée', array['business','droit','tech','art','comm','sciences'], 29680, 29680, array['en','es'], 4, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Université privée très internationale, avec des licences entièrement en anglais (business, droit, informatique, architecture…). Environ 26 500 à 29 000 € par an, plus le coût de la vie à Madrid. Très orientée entrepreneuriat, mais le prix la réserve aux familles aisées ou aux boursiers.', array['Licences 100 % en anglais avec des étudiants de plus de 100 pays','Forte culture entrepreneuriat et startups','Bons liens avec les entreprises pour les stages'], array['Cher : environ 30 000 $ par an rien qu''en frais','Diplôme moins connu qu''une grande université publique hors du monde des affaires','Campus de Ségovie petit et loin de Madrid pour certaines années'], 0, 'https://www.ie.edu/university/') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('unibo', 'Université de Bologne (Alma Mater Studiorum)', 'IT', 'Bologne', 'Publique', array['droit','business','sante','sciences','ingenierie','art','agri','education'], 176, 736, array['it','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Très grande université publique, bonne dans presque tous les domaines, avec de nombreux cursus en anglais. Pour les étudiants de pays en développement comme le Sénégal, il existe un forfait réduit d''environ 650 € par an. Le vrai problème : trouver un logement à Bologne, rare et de plus en plus cher.', array['Frais très bas pour les étudiants des pays en développement','Beaucoup de licences et masters en anglais','Vraie ville étudiante, très vivante'], array['Pénurie de logements, chambres chères et difficiles à trouver','Administration italienne lente (visa, permis de séjour)','Places limitées dans les cursus en anglais, sélection sur dossier ou test'], 0, 'https://www.unibo.it') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('polimi', 'Politecnico di Milano', 'IT', 'Milan', 'Publique', array['ingenierie','tech','art','sciences'], 187, 187, array['it','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'La grande école publique d''ingénieurs, d''architectes et de designers en Italie. Les frais dépendent des revenus de la famille, d''environ 170 € à 3 900 € par an : c''est bon marché pour ce niveau. Mais la licence est surtout en italien (l''anglais domine en master) et Milan est la ville la plus chère d''Italie.', array['Top mondial en design et architecture, excellent en ingénierie','Frais modestes calculés selon les revenus','Milan : beaucoup d''entreprises et de stages'], array['Licences surtout en italien, peu de choix en anglais','Milan est chère, surtout le logement','Rythme d''études très dur, beaucoup d''échecs en 1re année'], 0, 'https://www.polimi.it') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('sapienza', 'Sapienza Université de Rome', 'IT', 'Rome', 'Publique', array['sante','sciences','ingenierie','droit','art','business','comm'], 0, 336, array['it','en'], 3, 6, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Une des plus grandes universités d''Europe, au cœur de Rome, solide en médecine, ingénierie et sciences humaines. Les étudiants avec des revenus à l''étranger paient un forfait selon leur pays : environ 300 € par an pour les pays les moins riches. En revanche, c''est une université énorme et impersonnelle, avec une administration lente.', array['Frais très bas pour les étudiants africains','Large choix de cursus, dont plusieurs en anglais','Rome : coût de la vie plus doux que Milan'], array['Université immense, peu d''encadrement individuel','Lenteurs administratives et bâtiments parfois vieillissants','Beaucoup de licences seulement en italien'], 0, 'https://www.uniroma1.it') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('charles-university', 'Université Charles', 'CZ', 'Prague', 'Publique', array['sante','sciences','droit','art','business','education','tech'], 0, 0, array['cs','en'], 3, 6, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Très ancienne université publique de Prague, forte en médecine, sciences et sciences sociales. Les études en tchèque sont gratuites pour tous, mais en anglais il faut payer environ 5 000 à 7 000 € par an selon la faculté (médecine bien plus cher). Prague reste abordable comparée à l''Europe de l''Ouest.', array['Études gratuites en tchèque, même pour les étrangers','Réputation solide en médecine et en sciences','Coût de la vie plus bas qu''à Paris ou Madrid'], array['Cursus en anglais payants, médecine très chère (plus de 10 000 € par an)','Peu de licences en anglais','Le tchèque est une langue difficile à apprendre'], 0, 'https://cuni.cz') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('univ-warsaw', 'Université de Varsovie', 'PL', 'Varsovie', 'Publique', array['droit','business','sciences','tech','art','comm','education'], 0, 1120, array['pl','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'La plus grande université de Pologne, avec plusieurs licences en anglais (relations internationales, économie…). Pour un étudiant hors UE, compte environ 4 000 à 5 500 € par an selon le programme. C''est abordable, mais le climat est froid et la communauté africaine reste petite.', array['Frais et coût de la vie modérés pour l''Europe','Varsovie : économie en croissance, beaucoup d''emplois tech','Bonne réputation en économie et en maths'], array['Hivers très froids et longs','Communauté africaine petite, intégration parfois difficile','Peu de choix en anglais en licence'], 0, 'https://en.uw.edu.pl') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('elte', 'Université Eötvös Loránd (ELTE)', 'HU', 'Budapest', 'Publique', array['sciences','tech','education','droit','business','art','comm'], null, null, array['hu','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Grande université publique de Budapest, forte en informatique, sciences et lettres. En autofinancement, une licence coûte environ 4 000 € par an, mais la bourse Stipendium Hungaricum (ouverte au Sénégal) peut tout couvrir. Attention : la sélection pour cette bourse est forte et le hongrois est très difficile.', array['Bourse Stipendium Hungaricum accessible aux Sénégalais','Bon niveau en informatique et en maths','Budapest : ville agréable et assez bon marché'], array['Diplôme moins connu à l''international qu''une université d''Europe de l''Ouest','Hongrois très difficile, utile pour trouver un emploi sur place','Climat politique tendu sur l''immigration'], 0, 'https://www.elte.hu/en') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('univie', 'Université de Vienne', 'AT', 'Vienne', 'Publique', array['sciences','droit','business','art','education','comm','tech'], null, null, array['de','en'], 3, 5, 'Candidature directe à l''université (parfois via un portail national, comme Studielink aux Pays-Bas ou Universityadmissions en Suède). Diplôme de fin de lycée reconnu, parfois avec des matières exigées ; anglais ou langue du pays certifiés selon le programme.', 'Grande université publique au cœur de Vienne, solide en sciences, sciences sociales et lettres. Pour un étudiant hors UE, environ 727 € par semestre plus une petite cotisation étudiante : c''est très peu cher. Mais presque toutes les licences sont en allemand, avec un niveau C1 exigé.', array['Frais très bas même pour les non-Européens','Vienne : ville sûre, très bonne qualité de vie','Bonne réputation en recherche'], array['Licences presque toutes en allemand (niveau C1)','Amphithéâtres bondés, très peu de suivi personnel','Logement de plus en plus cher à Vienne'], 0, 'https://www.univie.ac.at') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('kaust', 'King Abdullah University of Science and Technology (KAUST)', 'SA', 'Thuwal', 'Privée', array['sciences','ingenierie','tech'], null, null, array['en'], 2, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université de recherche saoudienne qui ne fait que des masters et des doctorats en sciences et ingénierie : pas de licence. Tout est payé (frais, logement, santé) et tu reçois une allocation. Le prix à payer : une sélection très dure et un campus isolé au bord de la mer Rouge, loin des villes.', array['Études entièrement financées avec allocation mensuelle','Laboratoires et équipements de très haut niveau','Campus international, moderne et sûr'], array['Pas de licence : il faut déjà avoir un bachelor','Admission très sélective, il faut d''excellents résultats','Campus isolé, peu de vie en dehors'], 0, 'https://www.kaust.edu.sa') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('aub', 'American University of Beirut (AUB)', 'LB', 'Beyrouth', 'Privée', array['sante','ingenierie','business','sciences','agri','art','tech'], null, null, array['en'], 3, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université privée à l''américaine, la plus réputée du Liban, avec des cours en anglais et un très beau campus face à la mer. Les frais tournent autour de 850 à 1 050 $ par crédit, soit environ 28 000 $ par an. Le vrai point d''attention : la situation économique et sécuritaire du Liban, qui reste instable.', array['Diplôme très respecté au Moyen-Orient et aux États-Unis','Excellente en médecine, ingénierie et business','Vie de campus riche, cours en anglais'], array['Cher : environ 28 000 $ par an','Crise économique et instabilité sécuritaire au Liban','Aide financière surtout destinée aux Libanais'], 0, 'https://www.aub.edu.lb') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('universiti-malaya', 'Universiti Malaya (UM)', 'MY', 'Kuala Lumpur', 'Publique', array['ingenierie','tech','business','sante','sciences','droit','education'], null, null, array['en','ms'], 3, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'La plus ancienne et la plus prestigieuse université publique de Malaisie, avec beaucoup de cours en anglais. Une licence coûte environ 77 000 à 132 000 ringgits au total pour un étranger, soit environ 4 500 à 7 600 $ par an. Kuala Lumpur est bon marché, mais certaines matières restent en malais et la sélection est sérieuse.', array['Très bien classée pour un prix modéré','Coût de la vie bas à Kuala Lumpur','Grand campus avec résidences étudiantes'], array['Quelques cours obligatoires en malais','Peu de bourses de licence pour les étrangers','Difficile de travailler en Malaisie après les études avec un visa étudiant'], 0, 'https://www.um.edu.my') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('utp', 'Universiti Teknologi PETRONAS (UTP)', 'MY', 'Seri Iskandar (Perak)', 'Privée', array['ingenierie','tech','sciences','business'], null, null, array['en'], 4, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université d''ingénieurs créée par la compagnie pétrolière nationale malaisienne, avec tous les cours en anglais. Pour un étranger, environ 41 000 ringgits par an en ingénierie (environ 9 500 $), plus des frais d''inscription de 11 000 ringgits la 1re année. Le campus est isolé en zone rurale, loin de Kuala Lumpur.', array['Très forte en ingénierie pétrolière et chimique','Liens directs avec l''industrie de l''énergie et stages longs','Coût de la vie très bas sur place'], array['Campus isolé, peu de sorties','Frais de départ élevés (inscription 11 000 ringgits)','Débouchés liés au pétrole, secteur cyclique'], 0, 'https://www.utp.edu.my') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('utm', 'Universiti Teknologi Malaysia (UTM)', 'MY', 'Johor Bahru', 'Publique', array['ingenierie','tech','sciences','business','education'], null, null, array['en','ms'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Grande université publique d''ingénierie, avec un immense campus à Johor Bahru, juste à côté de Singapour. Une licence d''ingénieur coûte environ 75 000 ringgits au total pour un étranger (environ 4 300 $ par an), plus des frais d''inscription. Bon rapport qualité-prix, mais quelques cours restent en malais.', array['Bon rapport qualité-prix en ingénierie','Très grand campus avec résidences','Proche de Singapour, pôle d''emplois'], array['Quelques cours obligatoires en malais','Frais d''inscription semestriels en plus des frais de cours','Campus loin du centre-ville, voiture ou bus nécessaires'], 0, 'https://www.utm.my') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('taylors', 'Taylor''s University', 'MY', 'Subang Jaya (Kuala Lumpur)', 'Privée', array['business','tech','art','sante','comm','ingenierie','droit'], 9142, 11036, array['en'], 3, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université privée moderne près de Kuala Lumpur, avec tous les cours en anglais et un campus au bord d''un lac. Compte environ 10 000 $ par an pour une licence en informatique, plus 2 800 ringgits d''entrée. Excellente en hôtellerie et cuisine, mais diplôme moins prestigieux qu''une grande université publique.', array['Tous les cours en anglais, campus moderne','Très forte en hôtellerie, tourisme et cuisine','Licences courtes (environ 3 ans)'], array['Plus chère que les universités publiques malaisiennes','Réputation surtout régionale','Frais d''entrée et taxe de 6 % en plus pour les étrangers'], 0, 'https://university.taylors.edu.my') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('iit-delhi', 'Indian Institute of Technology Delhi (IIT Delhi)', 'IN', 'New Delhi', 'Publique', array['ingenierie','tech','sciences','business'], 2400, 4224, array['en'], 4, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Une des écoles d''ingénieurs les plus réputées d''Inde, dans la capitale. Pour un étranger hors Asie du Sud, environ 2 000 $ de frais par semestre plus les frais de résidence. Le défi n''est pas le prix mais l''admission : très peu de places pour les étrangers et un niveau en maths très élevé.', array['Niveau d''ingénierie parmi les meilleurs d''Asie','Très bons recrutements en tech et finance','Située à Delhi, proche des ministères et grandes entreprises'], array['Admission extrêmement sélective (JEE Advanced ou quota étranger limité)','Rythme de travail très intense, forte pression','Climat chaud, pollution et confort des résidences parfois basique'], 0, 'https://home.iitd.ac.in') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('iit-bombay', 'Indian Institute of Technology Bombay (IIT Bombay)', 'IN', 'Mumbai', 'Publique', array['ingenierie','tech','sciences','business'], 3078, 7878, array['en'], 4, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Un des IIT les plus demandés, à Mumbai, capitale économique de l''Inde, avec un grand campus vert au bord d''un lac. Pour un étranger, environ 308 000 roupies par semestre (environ 7 400 $ par an). L''admission est extrêmement sélective et Mumbai est chère pour se loger hors campus.', array['Niveau d''ingénierie parmi les meilleurs d''Asie','Très bons recrutements en tech et finance','Mumbai : capitale économique, finance et startups'], array['Admission extrêmement sélective (JEE Advanced ou quota étranger limité)','Rythme de travail très intense, forte pression','Climat chaud, pollution et confort des résidences parfois basique'], 0, 'https://www.iitb.ac.in') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('iit-madras', 'Indian Institute of Technology Madras (IIT Madras)', 'IN', 'Chennai', 'Publique', array['ingenierie','tech','sciences','business'], 2741, 12312, array['en'], 4, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Classé meilleur établissement d''Inde par le gouvernement depuis plusieurs années, avec un campus boisé à Chennai. Pour les étrangers, les frais sont élevés : 500 000 roupies par semestre (environ 12 300 $ par an), soit environ 4 fois le tarif indien. Chennai est très chaude et humide toute l''année.', array['Niveau d''ingénierie parmi les meilleurs d''Asie','Très bons recrutements en tech et finance','Grand incubateur de startups et parc de recherche sur le campus'], array['Admission extrêmement sélective (JEE Advanced ou quota étranger limité)','Rythme de travail très intense, forte pression','Climat chaud, pollution et confort des résidences parfois basique'], 0, 'https://www.iitm.ac.in') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('univ-delhi', 'University of Delhi', 'IN', 'New Delhi', 'Publique', array['business','sciences','droit','art','comm','education','tech'], null, null, array['en'], 3, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Énorme université publique organisée en dizaines de « colleges » (comme St. Stephen''s ou SRCC), forte en commerce, économie et lettres. Pour un étranger, compte des frais d''enregistrement (environ 53 000 roupies la 1re année puis 24 000 par an) plus les frais du college, donc souvent environ 1 000 à 1 500 $ par an hors filières pro. Les places en résidence sont rares et le niveau varie beaucoup d''un college à l''autre.', array['Frais très bas même pour les étrangers','Colleges réputés en commerce et économie','Cours en anglais et grande diversité de matières'], array['Très peu de places en résidence universitaire','Qualité très inégale selon le college','Pollution de l''air forte à Delhi en hiver'], 0, 'https://www.du.ac.in') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ntu-singapore', 'Nanyang Technological University (NTU)', 'SG', 'Singapour', 'Publique', array['tech','ingenierie','business','sciences','sante','comm','education'], 6391, 16478, array['en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Grande université publique de Singapour, très forte en ingénierie, informatique et sciences, avec un immense campus vert. Tout est en anglais et les diplômés trouvent facilement du travail en Asie. Le vrai point d''attention : l''admission est très sélective et, sans Tuition Grant, les frais dépassent 28 000 USD par an dans une ville chère.', array['Excellente en ingénierie, informatique et IA','Tout l''enseignement en anglais','Singapour : ville sûre, propre et bien connectée à toute l''Asie'], array['Frais élevés sans Tuition Grant, et le grant t''oblige à rester travailler 3 ans à Singapour','Logement privé très cher à Singapour','Admission très sélective pour les dossiers africains'], 0, 'https://www.ntu.edu.sg') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('smu-singapore', 'Singapore Management University', 'SG', 'Singapour', 'Publique', array['business','droit','tech'], 8894, 20174, array['en'], 4, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Petite université publique spécialisée en business, économie, droit et informatique, installée en plein centre-ville de Singapour. Les cours se font en petits groupes avec beaucoup de présentations orales et de stages. Le point d''attention : sans Tuition Grant, c''est l''une des options les plus chères d''Asie.', array['Campus en plein quartier d''affaires, proche des entreprises','Petites classes et stages obligatoires','Très bons débouchés en finance et comptabilité'], array['Plus de 36 000 USD/an sans Tuition Grant','Peu de filières hors business, droit et informatique','Pas de vrai campus résidentiel, logement cher'], 0, 'https://www.smu.edu.sg') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('peking-university', 'Peking University', 'CN', 'Pékin', 'Publique', array['sciences','business','droit','sante','tech','art','comm'], 700, 3640, array['zh','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'L''université la plus prestigieuse de Chine avec Tsinghua, forte en sciences, économie, lettres et médecine. Les frais sont bas (environ 26 000 à 30 000 CNY/an) mais la licence se fait presque entièrement en chinois. Le vrai point d''attention : il faut un très bon niveau de chinois (HSK élevé) et souvent passer un examen écrit.', array['Prestige énorme en Chine et en Asie','Frais très bas pour une université de ce niveau','Beau campus historique avec beaucoup d''activités'], array['Licence presque uniquement en chinois, niveau HSK élevé exigé','Logement à trouver soi-même sauf boursiers','Accès limité à certains sites et applis (Google, WhatsApp) sans VPN'], 0, 'https://english.pku.edu.cn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('fudan', 'Fudan University', 'CN', 'Shanghai', 'Publique', array['business','sante','sciences','droit','comm','tech'], 700, 3220, array['zh','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Grande université de Shanghai, réputée en économie, médecine, journalisme et relations internationales. Les licences en chinois coûtent entre 23 000 et 42 000 CNY par an selon la filière. Le point d''attention : la plupart des cours sont en chinois et Shanghai est une ville plus chère que le reste de la Chine.', array['Très bonne réputation en économie et médecine','Shanghai : grand centre d''affaires international','Quelques licences entièrement en anglais'], array['La plupart des licences sont en chinois (HSK exigé)','Vie plus chère à Shanghai qu''ailleurs en Chine','Accès limité à Google et WhatsApp sans VPN'], 0, 'https://www.fudan.edu.cn/en') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('sjtu', 'Shanghai Jiao Tong University', 'CN', 'Shanghai', 'Publique', array['ingenierie','tech','sante','business','sciences','agri'], 700, 3472, array['zh','en','fr'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Grande université d''ingénieurs à Shanghai, forte en mécanique, électronique, informatique, médecine et business. La licence en chinois coûte 24 800 CNY par an, mais les programmes en anglais d''ingénierie coûtent environ 120 000 CNY, soit près de 5 fois plus. Le point d''attention : bien vérifier la langue et le prix du programme choisi.', array['Parmi les meilleures écoles d''ingénieurs de Chine','Frais bas pour les licences en chinois','Liens historiques avec la France (programmes en français)'], array['Programmes en anglais beaucoup plus chers (environ 16 800 USD/an)','Pas de logement gratuit sur le campus','Accès limité à Google et WhatsApp sans VPN'], 0, 'https://en.sjtu.edu.cn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('zhejiang-university', 'Zhejiang University', 'CN', 'Hangzhou', 'Publique', array['ingenierie','tech','agri','sante','sciences','business'], 700, 2772, array['zh','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Très grande université de Hangzhou, ville tech où se trouve Alibaba. Elle couvre presque tout : ingénierie, informatique, agriculture, médecine, business. Les frais sont bas (24 800 CNY/an pour la plupart des licences, 42 800 pour la médecine en anglais). Le point d''attention : la majorité des cours sont en chinois.', array['Hangzhou : écosystème tech et e-commerce très actif','Frais bas et coût de la vie plus doux qu''à Shanghai','Très large choix de filières, y compris agriculture'], array['Majorité des licences en chinois (HSK exigé)','Moins connue que Pékin ou Shanghai hors de Chine','Accès limité à Google et WhatsApp sans VPN'], 0, 'https://www.zju.edu.cn/english') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('cuhk', 'Chinese University of Hong Kong', 'HK', 'Hong Kong', 'Publique', array['business','sante','sciences','tech','droit','comm','art','education'], 6016, 27392, array['en','zh'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Grande université de Hong Kong avec un système de colleges (résidences avec leur propre vie étudiante) sur une colline au bord de la mer. Les cours sont surtout en anglais, parfois en chinois. Le point d''attention : les non-locaux paient 214 000 HKD (environ 27 400 USD) par an, dans une ville où se loger coûte très cher.', array['Système de colleges qui crée une vraie vie de campus','Très bonne réputation en business, médecine et sciences','Bourses au mérite généreuses pour les très bons dossiers'], array['Frais élevés pour les non-locaux (environ 27 400 USD/an)','Hong Kong est l''une des villes les plus chères au monde pour se loger','Certains cours en cantonais ou en mandarin'], 0, 'https://www.cuhk.edu.hk') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('kyoto-university', 'Kyoto University', 'JP', 'Kyoto', 'Publique', array['sciences','ingenierie','sante','agri','droit','business'], 3590, 3590, array['ja','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université publique très prestigieuse, connue pour la recherche en sciences, médecine et ingénierie. Les frais sont bas (535 800 JPY par an, environ 3 600 USD), plus 282 000 JPY d''inscription à payer une fois. Le point d''attention : presque toutes les licences sont en japonais ; seuls quelques programmes (iUP, génie civil) sont accessibles sans parler japonais au départ.', array['Frais très bas pour une université de ce niveau','Excellente en recherche scientifique','Kyoto : ville historique, plus calme et moins chère que Tokyo'], array['Presque toutes les licences en japonais','Frais d''inscription de 282 000 JPY (environ 1 900 USD) à l''entrée','Peu de places dans les programmes ouverts aux étrangers'], 0, 'https://www.kyoto-u.ac.jp/en') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('osaka-university', 'Osaka University', 'JP', 'Osaka', 'Publique', array['sante','ingenierie','sciences','tech','education'], 3590, 3590, array['ja','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Grande université publique d''Osaka, forte en médecine, ingénierie, sciences et biologie. Mêmes frais bas que Kyoto (535 800 JPY par an) plus 282 000 JPY d''inscription. Le point d''attention : la plupart des licences sont en japonais ; les programmes en anglais (sciences humaines, chimie-biologie) ont très peu de places.', array['Frais très bas','Très forte en médecine, biologie et ingénierie','Osaka : grande ville vivante, moins chère que Tokyo'], array['La plupart des licences en japonais','Très peu de places dans les programmes en anglais','Campus éloignés du centre-ville'], 0, 'https://www.osaka-u.ac.jp/en') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('keio-university', 'Keio University', 'JP', 'Tokyo', 'Privée', array['business','sante','droit','tech','ingenierie','sciences'], null, null, array['ja','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'La plus ancienne université privée du Japon, très bien vue par les grandes entreprises japonaises. Les frais tournent autour de 1,3 million JPY par an (environ 8 800 USD) en économie ou droit, plus 200 000 JPY d''inscription, et bien plus en médecine. Le point d''attention : seuls deux programmes en anglais (PEARL et GIGA) existent en licence, le reste est en japonais.', array['Réseau d''anciens très puissant dans les entreprises japonaises','Programmes en anglais PEARL (économie) et GIGA (numérique, politiques)','Vie étudiante riche à Tokyo'], array['Tokyo : logement cher','Très peu de licences en anglais','Plus cher que les universités publiques japonaises'], 0, 'https://www.keio.ac.jp/en') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('waseda-university', 'Waseda University', 'JP', 'Tokyo', 'Privée', array['business','droit','comm','art','ingenierie','tech','sciences','education'], null, null, array['ja','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Grande université privée de Tokyo, très internationale, connue pour les sciences politiques, l''économie, les lettres et les médias. Elle propose plus de licences en anglais que la plupart des universités japonaises. Le point d''attention : les frais vont de 1,2 à 1,8 million JPY par an (8 000 à 12 000 USD) et la vie à Tokyo coûte cher.', array['Plusieurs licences entièrement en anglais','Beaucoup d''étudiants étrangers et de clubs','Bon réseau dans les médias, la politique et les entreprises'], array['Tokyo : logement et vie chers','Trouver un emploi au Japon demande souvent de parler japonais','Grandes classes en première année'], 0, 'https://www.waseda.jp/top/en') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('seoul-national-university', 'Seoul National University', 'KR', 'Séoul', 'Publique', array['sciences','ingenierie','sante','business','agri','art','education'], null, null, array['ko','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'La meilleure université publique de Corée, forte dans presque tous les domaines. Les frais sont bas (environ 6 millions KRW par an en moyenne, soit 4 400 USD). Le point d''attention : la quasi-totalité des cours de licence est en coréen, donc il faut apprendre le coréen (TOPIK) avant ou dès l''arrivée.', array['Prestige maximal en Corée','Frais bas pour ce niveau','Grand campus avec résidences abordables'], array['Licence presque entièrement en coréen (TOPIK exigé)','Rythme d''études très intense','Campus en colline, loin du centre de Séoul'], 0, 'https://en.snu.ac.kr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('yonsei-university', 'Yonsei University', 'KR', 'Séoul', 'Privée', array['business','sante','ingenierie','tech','comm','sciences'], null, null, array['ko','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Grande université privée de Séoul, très forte en médecine, business et ingénierie. Son Underwood International College (UIC) propose des licences entièrement en anglais. Le point d''attention : l''UIC coûte environ 16,8 millions KRW par an (12 300 USD), presque deux fois plus que les filières en coréen.', array['Licences entièrement en anglais à l''UIC','Campus vivant dans le quartier étudiant de Sinchon','Très bonne réputation en médecine et business'], array['UIC nettement plus cher que les filières en coréen','Trouver un travail en Corée demande souvent le coréen','Première année parfois sur le campus de Songdo, loin du centre'], 0, 'https://www.yonsei.ac.kr/en_sc') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('korea-university', 'Korea University', 'KR', 'Séoul', 'Privée', array['business','ingenierie','sante','comm','sciences','tech'], null, null, array['ko','en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Grande université privée de Séoul, connue pour son école de business, son réseau d''anciens et sa forte vie étudiante. Pour un étudiant étranger, compte environ 11,6 millions KRW par an en sciences humaines et 15,4 millions en ingénierie. Le point d''attention : la plupart des cours sont en coréen, avec seulement quelques programmes en anglais.', array['École de business très réputée en Corée','Réseau d''anciens puissant et vie étudiante intense','Beaucoup d''étudiants internationaux et d''échanges'], array['La plupart des cours en coréen (TOPIK souvent exigé)','Ingénierie plus chère (environ 11 200 USD/an)','Peu de licences entièrement en anglais'], 0, 'https://www.korea.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('wits', 'University of the Witwatersrand (Wits)', 'ZA', 'Johannesburg', 'Publique', array['business','sante','tech','droit','sciences','ingenierie','art'], null, null, array['en'], 3, 6, 'Équivalence du diplôme via Universities South Africa (exemption), résultats suffisants dans les matières requises, anglais certifié pour les non-anglophones.', 'Grande université de recherche au cœur de Johannesburg, forte en médecine, ingénierie, mines, commerce et droit. Un des meilleurs diplômes du continent pour un coût bien plus bas qu''en Europe. Attention : hors SADC (Sénégal, Afrique de l''Ouest…), tu paies le double des frais locaux, et la sécurité en ville demande de la vigilance.', array['Diplôme très reconnu en Afrique et à l''international','Au centre économique du continent : stages et réseau d''entreprises','Excellentes filières en ingénierie, mines et santé'], array['Frais doublés pour les étudiants africains hors SADC','Insécurité dans certains quartiers de Johannesburg','Manifestations étudiantes sur les frais qui perturbent parfois l''année'], 0, 'https://www.wits.ac.za') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('stellenbosch', 'Stellenbosch University', 'ZA', 'Stellenbosch (Cap-Occidental)', 'Publique', array['business','sante','sciences','ingenierie','agri','droit','art'], 3161, 5573, array['en'], 3, 6, 'Équivalence du diplôme via Universities South Africa (exemption), résultats suffisants dans les matières requises, anglais certifié pour les non-anglophones.', 'Université de recherche dans une petite ville étudiante près du Cap, connue pour l''agronomie, le vin, l''ingénierie, la médecine et le commerce. Vie de campus très riche et cadre sûr comparé aux grandes villes. Attention : une taxe internationale importante s''ajoute pour les étudiants hors SADC, et certains cours de 1re année restent partiellement en afrikaans.', array['Ville étudiante agréable et plus sûre que Johannesburg','Très forte en agronomie, vin et sciences de la vie','Vie de campus et associations très actives'], array['Logement cher et rare à Stellenbosch','Héritage afrikaans encore présent dans certains cours et la culture','Taxe internationale élevée pour les étudiants hors SADC'], 0, 'https://www.su.ac.za') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('pretoria', 'University of Pretoria', 'ZA', 'Pretoria', 'Publique', array['business','sante','tech','droit','sciences','ingenierie','agri','education'], 3300, 6772, array['en'], 3, 6, 'Équivalence du diplôme via Universities South Africa (exemption), résultats suffisants dans les matières requises, anglais certifié pour les non-anglophones.', 'Une des plus grandes universités d''Afrique du Sud, avec presque toutes les filières, dont la seule faculté vétérinaire du pays et une grande école de commerce (GIBS). Pretoria est plus calme que Johannesburg. Attention : les étudiants hors SADC paient le double des frais locaux.', array['Choix de filières très large','Seule faculté vétérinaire d''Afrique du Sud','Ville administrative, proche des ambassades et ministères'], array['Frais doublés pour les étudiants hors SADC','Grandes promotions, peu de suivi individuel en 1re année'], 0, 'https://www.up.ac.za') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('rhodes', 'Rhodes University', 'ZA', 'Makhanda (Cap-Oriental)', 'Publique', array['business','comm','droit','sciences','art','education','sante'], 2498, 3469, array['en'], 3, 5, 'Équivalence du diplôme via Universities South Africa (exemption), résultats suffisants dans les matières requises, anglais certifié pour les non-anglophones.', 'Petite université résidentielle dans une ville étudiante, connue pour le journalisme, les sciences et les lettres. On y vit surtout en résidence, avec un encadrement plus proche que dans les grandes universités. Attention : la ville est petite et isolée, avec des coupures d''eau et d''électricité fréquentes.', array['Petite taille : professeurs accessibles','École de journalisme et médias très réputée','Frais pour étrangers plus bas que Wits ou Pretoria'], array['Ville isolée avec coupures d''eau et d''électricité','Pas de médecine ni d''ingénierie','Peu de stages et d''entreprises sur place'], 0, 'https://www.ru.ac.za') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('unisa', 'University of South Africa (UNISA)', 'ZA', 'Pretoria (à distance)', 'En ligne', array['business','droit','education','sciences','tech','art','agri'], 2274, 3347, array['en'], 3, 6, 'Équivalence du diplôme via Universities South Africa (exemption), résultats suffisants dans les matières requises, anglais certifié pour les non-anglophones.', 'Université publique 100 % à distance : tu étudies depuis chez toi et tu passes des examens, avec un diplôme sud-africain reconnu. Bon choix si tu travailles ou si tu ne peux pas partir. Attention : beaucoup d''étudiants abandonnent, il faut être très autonome, et une taxe s''ajoute par module si tu vis hors d''Afrique du Sud.', array['Étudier sans quitter son pays ni son travail','Frais bas, payés par module','Diplôme public reconnu'], array['Taux d''abandon élevé, très peu d''encadrement','Aucune vie étudiante ni réseau sur place','Plateforme et administration parfois lentes'], 0, 'https://www.unisa.ac.za') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('cairo-university', 'Cairo University', 'EG', 'Le Caire (Gizeh)', 'Publique', array['sante','ingenierie','droit','business','sciences','comm','agri','art'], null, null, array['ar','en'], 4, 6, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Immense université publique (plus de 200 000 étudiants), forte en médecine, ingénierie et droit. Les étudiants étrangers paient des frais en dollars, bien plus élevés que les Égyptiens. Attention : beaucoup de cours sont en arabe, les amphis sont bondés, et l''administration est lente.', array['Diplôme reconnu dans le monde arabe et en Afrique','Coût de la vie bas au Caire','Programmes en anglais dans certaines facultés (crédits)'], array['Beaucoup de cours en arabe','Amphis surchargés et bureaucratie lourde','Frais pour étrangers bien plus élevés que pour les Égyptiens'], 0, 'https://cu.edu.eg') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('auc', 'American University in Cairo (AUC)', 'EG', 'Le Caire (New Cairo)', 'Privée', array['business','tech','ingenierie','sciences','comm','art','droit'], 16800, 17640, array['en'], 4, 6, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Université privée de style américain, tout en anglais, avec un campus moderne et un réseau puissant au Moyen-Orient. Bon choix pour le business, l''informatique ou les relations internationales. Attention : le prix est celui d''une université américaine (plus de 20 000 $ par an), sauf si tu obtiens une bourse.', array['Diplôme accrédité aux États-Unis, tout en anglais','Campus moderne et vie étudiante riche','Réseau d''anciens très présent au Moyen-Orient'], array['Très cher pour le niveau de vie de la région','Campus loin du centre-ville, trajets longs'], 0, 'https://www.aucegypt.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('tunis-el-manar', 'Université de Tunis El Manar', 'TN', 'Tunis', 'Publique', array['sante','ingenierie','sciences','tech','droit','business'], null, null, array['fr','ar'], 3, 5, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Grande université publique de Tunis qui regroupe des facultés de médecine, sciences, droit et l''école d''ingénieurs ENIT. Les cours sont surtout en français, ce qui facilite la vie aux francophones. Attention : les étrangers passent par un « programme payant » avec des frais bien plus élevés que les Tunisiens, et les places sont limitées.', array['Enseignement en français','Bonnes formations en médecine et ingénierie (ENIT)','Coût de la vie modéré à Tunis'], array['Procédure d''admission des étrangers lente (validation du ministère)','Moyens matériels limités et bureaucratie','Discrimination signalée envers les étudiants subsahariens'], 0, 'https://utm.rnu.tn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('esca', 'ESCA École de Management', 'MA', 'Casablanca', 'Privée', array['business','comm'], 8360, 8360, array['fr','en'], 3, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'École de commerce privée à Casablanca avec une licence (Bac+3) et un Programme Grande École (Bac+5), en français ou en anglais. Bonne porte d''entrée vers le monde des affaires au Maroc et en Afrique de l''Ouest. Attention : environ 76 000 dirhams par an plus 6 000 de frais d''inscription, et le diplôme est moins connu hors d''Afrique qu''une école française.', array['Cours en français, avec un parcours 100 % anglais','Casablanca : capitale économique avec beaucoup de stages','Accords d''échange avec des écoles européennes'], array['Frais élevés pour la région','Uniquement du commerce et du management','Logement cher dans les bons quartiers de Casablanca'], 0, 'https://esca.ma') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('knust', 'Kwame Nkrumah University of Science and Technology (KNUST)', 'GH', 'Kumasi', 'Publique', array['ingenierie','tech','sciences','sante','agri','business','art'], 400, 4430, array['en'], 4, 6, 'WASSCE ou diplôme équivalent avec des crédits dans les matières clés. Les candidats internationaux postulent en ligne au guichet international.', 'La grande université technologique du Ghana, réputée pour l''ingénierie, l''architecture, la pharmacie et l''agriculture, sur un grand campus vert à Kumasi. Bonne option anglophone et abordable pour un étudiant d''Afrique de l''Ouest. Attention : les étrangers paient entre 4 400 et 7 600 $ par an selon la filière, soit beaucoup plus que les Ghanéens, et les grèves peuvent décaler le calendrier.', array['Très forte en ingénierie et sciences appliquées','Grand campus avec résidences et vie étudiante animée','Pays stable, proche de l''Afrique de l''Ouest francophone'], array['Grèves du personnel qui perturbent parfois l''année','Équipements de laboratoire parfois limités','Tout en anglais : niveau solide nécessaire'], 0, 'https://www.knust.edu.gh') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ibadan', 'University of Ibadan', 'NG', 'Ibadan', 'Publique', array['sante','sciences','droit','agri','education','art','business','ingenierie'], null, null, array['en'], 4, 6, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Plus ancienne université du Nigeria, réputée pour la médecine, l''agriculture et les sciences humaines. Les frais sont bas et le diplôme est respecté en Afrique de l''Ouest anglophone. Attention : les grèves des enseignants (ASUU) ont souvent bloqué les universités publiques nigérianes pendant des mois, et l''admission passe par des procédures nigérianes complexes.', array['Frais et coût de la vie très bas','Bonne réputation en médecine et agriculture','Grand réseau d''anciens au Nigeria'], array['Grèves longues et fréquentes (ASUU)','Coupures d''électricité et infrastructures usées','Peu d''information officielle pour les étrangers'], 0, 'https://ui.edu.ng') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('nairobi', 'University of Nairobi', 'KE', 'Nairobi', 'Publique', array['sante','ingenierie','droit','business','sciences','tech','agri','comm','art'], 1109, 1109, array['en'], 4, 6, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Plus grande université du Kenya, au cœur de Nairobi, une ville pleine de startups, d''ONG et de sièges des Nations unies. Forte en médecine, droit, ingénierie et commerce. Attention : le financement des universités publiques kényanes est instable, avec des hausses de frais et des grèves récentes.', array['Nairobi : hub tech et ONG d''Afrique de l''Est','Diplôme respecté dans toute l''Afrique de l''Est','Large choix de filières'], array['Grèves et changements de frais fréquents','Grandes promotions, peu d''encadrement','Vigilance nécessaire en ville (vols)'], 0, 'https://www.uonbi.ac.ke') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('makerere', 'Makerere University', 'UG', 'Kampala', 'Publique', array['sante','agri','sciences','tech','business','droit','education','art','ingenierie'], 786, 1380, array['en'], 3, 5, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Une des plus anciennes et prestigieuses universités d''Afrique de l''Est, forte en santé publique, agriculture et sciences. Les frais sont parmi les plus bas de cette liste, même pour les étrangers. Attention : les infrastructures sont vieillissantes et les grèves du personnel arrivent régulièrement.', array['Frais très bas pour une université reconnue','Forte en santé publique et agriculture','Bourses Mastercard Foundation pour Africains'], array['Bâtiments et équipements vieillissants','Grèves du personnel et retards administratifs','Peu connue en Afrique francophone'], 0, 'https://www.mak.ac.ug') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('rwanda', 'University of Rwanda', 'RW', 'Kigali (et autres campus)', 'Publique', array['sante','tech','ingenierie','business','agri','education','sciences'], 420, 504, array['en'], 4, 6, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Université publique créée en 2013 en fusionnant les établissements publics du pays, avec des campus dans plusieurs villes. Kigali est une capitale propre, sûre et tournée vers la tech. Attention : les cours sont en anglais, la qualité varie selon les campus, et les informations officielles sur les frais sont peu à jour.', array['Pays sûr et stable','Frais abordables','Kigali : écosystème tech et startups en croissance'], array['Reconnaissance internationale encore limitée','Campus dispersés et qualité inégale','Kigali assez cher pour se loger'], 0, 'https://ur.ac.rw') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('addis-ababa', 'Addis Ababa University', 'ET', 'Addis-Abeba', 'Publique', array['sante','ingenierie','sciences','business','droit','art','education','comm'], null, null, array['en'], 4, 6, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Plus ancienne et plus grande université d''Éthiopie, dans la ville qui accueille le siège de l''Union africaine. Bonne pour la médecine, l''ingénierie et les études africaines. Attention : l''admission des étrangers est peu documentée, l''internet est parfois coupé, et le pays connaît des tensions politiques.', array['Siège de l''Union africaine : stages en relations internationales','Coût de la vie bas','Bonne réputation en médecine et ingénierie'], array['Tensions politiques et coupures d''internet','Très peu d''informations pour les étrangers','Calendrier éthiopien et procédures différentes'], 0, 'https://www.aau.edu.et') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('dar-es-salaam', 'University of Dar es Salaam', 'TZ', 'Dar es Salaam', 'Publique', array['ingenierie','sciences','droit','business','education','art','comm','tech','sante'], 480, 2700, array['en'], 3, 5, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Plus ancienne université de Tanzanie, sur une colline à Dar es Salaam, connue pour le droit, les sciences sociales et l''ingénierie. Le pays est stable et la vie peu chère. Attention : les étrangers paient en dollars, bien plus que les Tanzaniens, et le swahili domine la vie quotidienne hors des cours.', array['Pays stable et paisible','Bonne réputation en droit et sciences sociales','Coût de la vie bas'], array['Frais pour étrangers peu publiés et bien plus élevés','Swahili indispensable au quotidien','Climat chaud et humide, transports lents'], 0, 'https://www.udsm.ac.tz') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-eiffel-2027', 'bourse', 'Bourse d''excellence Eiffel 2027', 'Campus France — ministère de l''Europe et des Affaires étrangères', 'FR', null, 'droit', 'Allocation mensuelle + frais annexes (voyage, assurance, activités culturelles) — montants sur la page officielle', null, 'master', '2027-01-06', 'Étudiants étrangers en master ou en doctorat. C''est l''établissement français qui dépose ton dossier.', 'https://www.campusfrance.org/fr/le-programme-de-bourses-d-excellence-eiffel', false, '{"id":"b-eiffel-2027","type":"bourse","titre":"Bourse d''excellence Eiffel 2027","organisation":"Campus France — ministère de l''Europe et des Affaires étrangères","pays":"FR","domaine":"droit","domaines":["droit","business","ingenierie","sciences","tech"],"niveau":"master","niveaux":["master","doctorat"],"montant":{"fr":"Allocation mensuelle + frais annexes (voyage, assurance, activités culturelles) — montants sur la page officielle","en":"Monthly allowance + extra costs (travel, insurance, cultural activities) — amounts on the official page"},"eligibles":{"fr":"Étudiants étrangers en master ou en doctorat. C''est l''établissement français qui dépose ton dossier.","en":"International master’s or PhD students. The French institution submits your application."},"ouverture":"2026-10-02","deadline":"2027-01-06","deadlineNote":{"fr":"Date limite pour l''établissement français qui dépose ton dossier. Ton établissement fixe une date plus tôt : demande-la-lui dès maintenant.","en":"Deadline for the French institution that submits your file. Your institution sets an earlier date: ask for it now."},"lien":"https://www.campusfrance.org/fr/le-programme-de-bourses-d-excellence-eiffel","source":"campusfrance.org","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-10-02', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-suisse-2027', 'bourse', 'Bourses d’excellence de la Confédération suisse 2027-2028', 'Commission fédérale des bourses (CFBE / ESKAS) — Suisse', 'CH', null, 'sciences', 'Bourse de recherche ou de doctorat (jusqu’à 36 mois pour un doctorat)', null, 'doctorat', '2026-11-30', 'Titulaires d’un master, avec un professeur en Suisse qui soutient ton projet de recherche. Dossier déposé via l’ambassade de Suisse de ton pays.', 'https://www.sbfi.admin.ch/en/swiss-government-excellence-scholarships-at-a-glance', false, '{"id":"b-suisse-2027","type":"bourse","titre":"Bourses d’excellence de la Confédération suisse 2027-2028","organisation":"Commission fédérale des bourses (CFBE / ESKAS) — Suisse","pays":"CH","domaine":"sciences","domaines":["sciences","sante","ingenierie","business","droit","education","agri","tech"],"niveau":"doctorat","niveaux":["doctorat"],"montant":{"fr":"Bourse de recherche ou de doctorat (jusqu’à 36 mois pour un doctorat)","en":"Research or PhD scholarship (up to 36 months for a PhD)"},"eligibles":{"fr":"Titulaires d’un master, avec un professeur en Suisse qui soutient ton projet de recherche. Dossier déposé via l’ambassade de Suisse de ton pays.","en":"Master’s graduates with a professor in Switzerland backing your research project. Apply through the Swiss embassy in your country."},"ouverture":"2026-08-20","deadline":"2026-11-30","deadlines":{"SN":"2026-11-30","ML":"2026-11-30","GA":"2026-11-30","CG":"2026-11-30","CD":"2026-11-30","KE":"2026-11-30","CI":"2026-11-27","CM":"2026-11-27","BJ":"2026-11-27","TG":"2026-11-27","BF":"2026-11-27","GN":"2026-11-27","NE":"2026-11-27","MG":"2026-11-27","NG":"2026-11-27","GH":"2026-11-27","DZ":"2026-11-13","MA":"2026-11-10","TN":"2026-10-13"},"deadlineNote":{"fr":"La date limite dépend de ton pays : elle est affichée pour ton pays quand il est dans la liste officielle.","en":"The deadline depends on your country: it is shown for your country when it is on the official list."},"lien":"https://www.sbfi.admin.ch/en/swiss-government-excellence-scholarships-at-a-glance","source":"sbfi.admin.ch (liste officielle Afrique, 4 août 2026)","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-08-20', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-commonwealth-master-2027', 'bourse', 'Bourses de master du Commonwealth 2027-2028', 'Commonwealth Scholarship Commission (Royaume-Uni)', 'GB', null, 'sciences', 'Billet d’avion, frais de scolarité complets et allocation de 1 712 £ par mois (2 000 £ à Londres)', null, 'master', '2026-10-20', 'Citoyens de pays du Commonwealth à revenu faible ou intermédiaire (Ghana, Kenya, Nigeria, Cameroun, Afrique du Sud…). Candidature via un organisme national qui te présente.', 'https://cscuk.fcdo.gov.uk/scholarships/commonwealth-masters-scholarships/', false, '{"id":"b-commonwealth-master-2027","type":"bourse","titre":"Bourses de master du Commonwealth 2027-2028","organisation":"Commonwealth Scholarship Commission (Royaume-Uni)","pays":"GB","domaine":"sciences","domaines":["sciences","sante","ingenierie","agri","education","business","tech"],"niveau":"master","niveaux":["master"],"montant":{"fr":"Billet d’avion, frais de scolarité complets et allocation de 1 712 £ par mois (2 000 £ à Londres)","en":"Airfare, full tuition and a £1,712 monthly stipend (£2,000 in London)"},"eligibles":{"fr":"Citoyens de pays du Commonwealth à revenu faible ou intermédiaire (Ghana, Kenya, Nigeria, Cameroun, Afrique du Sud…). Candidature via un organisme national qui te présente.","en":"Citizens of low- and middle-income Commonwealth countries (Ghana, Kenya, Nigeria, Cameroon, South Africa…). You apply through a national nominating body."},"deadline":"2026-10-20","deadlineNote":{"fr":"Clôture le 20 octobre 2026 à 16 h (heure de Londres). L’organisme de ton pays peut fixer une date plus tôt.","en":"Closes 20 October 2026 at 16:00 UK time. Your national nominating body may set an earlier date."},"lien":"https://cscuk.fcdo.gov.uk/scholarships/commonwealth-masters-scholarships/","source":"cscuk.fcdo.gov.uk","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-yenching-2027', 'bourse', 'Yenching Academy — master en études chinoises 2027', 'Université de Pékin (Peking University)', 'CN', null, 'droit', 'Frais de scolarité, logement, allocation mensuelle, un aller-retour en avion et voyages d’étude', null, 'master', '2026-11-30', 'Titulaires d’une licence (ou en dernière année), toutes nationalités, bon niveau d’anglais.', 'https://yenchingacademy.pku.edu.cn/ADMISSIONS.htm', false, '{"id":"b-yenching-2027","type":"bourse","titre":"Yenching Academy — master en études chinoises 2027","organisation":"Université de Pékin (Peking University)","pays":"CN","domaine":"droit","domaines":["droit","business","comm","education","art"],"niveau":"master","niveaux":["master"],"montant":{"fr":"Frais de scolarité, logement, allocation mensuelle, un aller-retour en avion et voyages d’étude","en":"Tuition, accommodation, monthly stipend, one round-trip flight and field-study trips"},"eligibles":{"fr":"Titulaires d’une licence (ou en dernière année), toutes nationalités, bon niveau d’anglais.","en":"Bachelor’s graduates (or final-year students), any nationality, strong English."},"deadline":"2026-11-30","deadlineNote":{"fr":"Clôture le 30 novembre 2026 à 9 h, heure de Pékin (1 h du matin à Dakar).","en":"Closes 30 November 2026 at 9:00 Beijing time."},"lien":"https://yenchingacademy.pku.edu.cn/ADMISSIONS.htm","source":"yenchingacademy.pku.edu.cn","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-ens-intl-2027', 'bourse', 'Sélection internationale de l’ENS 2027', 'École normale supérieure – PSL (Paris)', 'FR', null, 'sciences', '1 000 € par mois pendant 3 ans + une chambre sur un campus de l’ENS', null, 'licence', '2026-12-15', 'Toutes nationalités, moins de 26 ans au 16 octobre 2026, au moins 1 an (sciences) ou 3 ans (lettres) d’études supérieures hors de France.', 'https://www.ens.psl.eu/en/une-formation-d-exception/admissions/international/international-selection', false, '{"id":"b-ens-intl-2027","type":"bourse","ageMax":25,"titre":"Sélection internationale de l’ENS 2027","organisation":"École normale supérieure – PSL (Paris)","pays":"FR","domaine":"sciences","domaines":["sciences","art","education","droit"],"niveau":"licence","niveaux":["licence","master"],"montant":{"fr":"1 000 € par mois pendant 3 ans + une chambre sur un campus de l’ENS","en":"€1,000 a month for 3 years + a room on an ENS campus"},"eligibles":{"fr":"Toutes nationalités, moins de 26 ans au 16 octobre 2026, au moins 1 an (sciences) ou 3 ans (lettres) d’études supérieures hors de France.","en":"Any nationality, under 26 on 16 October 2026, at least 1 year (sciences) or 3 years (humanities) of higher education outside France."},"ouverture":"2026-10-16","deadline":"2026-12-15","deadlineNote":{"fr":"Candidature du 16 octobre au 15 décembre 2026, 14 h (heure de Paris), sur la plateforme OnePSL.","en":"Apply from 16 October to 15 December 2026, 14:00 Paris time, on the OnePSL platform."},"lien":"https://www.ens.psl.eu/en/une-formation-d-exception/admissions/international/international-selection","source":"ens.psl.eu","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-10-16', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-eth-esop-2027', 'bourse', 'Excellence Scholarship (ESOP) — master à l’ETH Zurich', 'ETH Zurich (Suisse)', 'CH', null, 'ingenierie', '13 500 CHF par semestre + frais de scolarité offerts', null, 'master', '2026-11-30', 'Étudiants parmi les 10 % meilleurs de leur promotion de licence, qui postulent à un master de l’ETH.', 'https://ethz.ch/en/studies/financial/scholarships/excellencescholarship.html', false, '{"id":"b-eth-esop-2027","type":"bourse","titre":"Excellence Scholarship (ESOP) — master à l’ETH Zurich","organisation":"ETH Zurich (Suisse)","pays":"CH","domaine":"ingenierie","domaines":["ingenierie","sciences","tech","agri"],"niveau":"master","niveaux":["master"],"montant":{"fr":"13 500 CHF par semestre + frais de scolarité offerts","en":"CHF 13,500 per semester + tuition waiver"},"eligibles":{"fr":"Étudiants parmi les 10 % meilleurs de leur promotion de licence, qui postulent à un master de l’ETH.","en":"Students in the top 10% of their bachelor’s class applying to an ETH master’s."},"ouverture":"2026-11-01","deadline":"2026-11-30","deadlineNote":{"fr":"Candidature du 1er au 30 novembre 2026, en même temps que la candidature au master.","en":"Apply from 1 to 30 November 2026, together with your master’s application."},"lien":"https://ethz.ch/en/studies/financial/scholarships/excellencescholarship.html","source":"ethz.ch","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-11-01', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-epfl-excellence-2027', 'bourse', 'Bourses d’excellence pour le master — EPFL', 'École polytechnique fédérale de Lausanne (EPFL)', 'CH', null, 'ingenierie', '10 000 CHF par semestre, jusqu’à 4 semestres', null, 'master', '2026-12-15', 'Excellents étudiants venant d’une autre université, qui postulent à un master de l’EPFL.', 'https://www.epfl.ch/education/master/master-excellence-fellowships/how-to-apply/', false, '{"id":"b-epfl-excellence-2027","type":"bourse","titre":"Bourses d’excellence pour le master — EPFL","organisation":"École polytechnique fédérale de Lausanne (EPFL)","pays":"CH","domaine":"ingenierie","domaines":["ingenierie","sciences","tech"],"niveau":"master","niveaux":["master"],"montant":{"fr":"10 000 CHF par semestre, jusqu’à 4 semestres","en":"CHF 10,000 per semester, up to 4 semesters"},"eligibles":{"fr":"Excellents étudiants venant d’une autre université, qui postulent à un master de l’EPFL.","en":"Outstanding students from another university applying to an EPFL master’s."},"deadline":"2026-12-15","deadlineNote":{"fr":"Pour les candidats externes : dépôt avec la candidature au master, au plus tard le 15 décembre.","en":"For external applicants: submit with your master’s application by 15 December."},"lien":"https://www.epfl.ch/education/master/master-excellence-fellowships/how-to-apply/","source":"epfl.ch","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-oxford-clarendon-2027', 'bourse', 'Bourses Clarendon — Université d’Oxford 2027-2028', 'Université d’Oxford', 'GB', null, 'sciences', 'Frais de scolarité complets + allocation de vie (au moins le minimum doctoral britannique)', null, 'master', '2027-01-26', 'Toutes nationalités. Tu es examiné automatiquement si tu postules à ton master ou doctorat avant la date limite du cours.', 'https://www.ox.ac.uk/admissions/graduate/fees-and-funding/funding/clarendon/applicants', false, '{"id":"b-oxford-clarendon-2027","type":"bourse","titre":"Bourses Clarendon — Université d’Oxford 2027-2028","organisation":"Université d’Oxford","pays":"GB","domaine":"sciences","domaines":["sciences","sante","ingenierie","droit","business","art","education","tech"],"niveau":"master","niveaux":["master","doctorat"],"montant":{"fr":"Frais de scolarité complets + allocation de vie (au moins le minimum doctoral britannique)","en":"Full course fees + living grant (at least the UK minimum doctoral stipend)"},"eligibles":{"fr":"Toutes nationalités. Tu es examiné automatiquement si tu postules à ton master ou doctorat avant la date limite du cours.","en":"Any nationality. You are considered automatically if you apply to your course by its deadline."},"deadline":"2027-01-26","deadlineNote":{"fr":"La date dépend du cours : certains ferment début décembre, d’autres en janvier (ex. : 26 janvier 2027). Vérifie la page de ton cours.","en":"The date depends on the course: some close in early December, others in January (e.g. 26 January 2027). Check your course page."},"lien":"https://www.ox.ac.uk/admissions/graduate/fees-and-funding/funding/clarendon/applicants","source":"ox.ac.uk","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-oxford-weidenfeld-2027', 'bourse', 'Bourses Weidenfeld-Hoffmann — Oxford 2027-2028', 'Université d’Oxford et Weidenfeld-Hoffmann Trust', 'GB', null, 'droit', '100 % des frais de scolarité + allocation de vie (au moins 21 805 £)', null, 'master', '2027-01-26', 'Citoyens des pays listés (presque toute l’Afrique, dont le Sénégal), pour une quarantaine de masters (politiques publiques, MBA, économie du développement, informatique…).', 'https://www.ox.ac.uk/admissions/graduate/fees-and-funding/fees-funding-and-scholarship-search/weidenfeld-hoffmann-scholarships-and-leadership-programme', false, '{"id":"b-oxford-weidenfeld-2027","type":"bourse","titre":"Bourses Weidenfeld-Hoffmann — Oxford 2027-2028","organisation":"Université d’Oxford et Weidenfeld-Hoffmann Trust","pays":"GB","domaine":"droit","domaines":["droit","business","sciences","tech","ingenierie"],"niveau":"master","niveaux":["master"],"montant":{"fr":"100 % des frais de scolarité + allocation de vie (au moins 21 805 £)","en":"100% of course fees + living grant (at least £21,805)"},"eligibles":{"fr":"Citoyens des pays listés (presque toute l’Afrique, dont le Sénégal), pour une quarantaine de masters (politiques publiques, MBA, économie du développement, informatique…).","en":"Citizens of listed countries (almost all of Africa, including Senegal), for about 40 master’s courses (public policy, MBA, development economics, computer science…)."},"deadline":"2027-01-26","deadlineNote":{"fr":"Coche la bourse dans ta candidature au master et ajoute la déclaration demandée, avant la date limite de ton cours (décembre ou janvier).","en":"Select the scholarship in your master’s application and add the required statement before your course deadline (December or January)."},"lien":"https://www.ox.ac.uk/admissions/graduate/fees-and-funding/fees-funding-and-scholarship-search/weidenfeld-hoffmann-scholarships-and-leadership-programme","source":"ox.ac.uk","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-erasmus-mundus-2027', 'bourse', 'Bourses Erasmus Mundus — masters conjoints en Europe', 'Commission européenne (EACEA)', 'EU', null, 'sciences', 'Frais de participation, voyage, visa et allocation de vie pendant tout le master (2 ans dans 2 pays ou plus)', null, 'master', '2027-01-31', 'Titulaires d’une licence, toutes nationalités. Tu postules directement au master choisi dans le catalogue.', 'https://www.eacea.ec.europa.eu/scholarships/erasmus-mundus-catalogue_en', false, '{"id":"b-erasmus-mundus-2027","type":"bourse","titre":"Bourses Erasmus Mundus — masters conjoints en Europe","organisation":"Commission européenne (EACEA)","pays":"EU","domaine":"sciences","domaines":["sciences","ingenierie","tech","sante","agri","business","education","droit","art"],"niveau":"master","niveaux":["master"],"montant":{"fr":"Frais de participation, voyage, visa et allocation de vie pendant tout le master (2 ans dans 2 pays ou plus)","en":"Participation costs, travel, visa and living allowance for the whole master’s (2 years in 2 or more countries)"},"eligibles":{"fr":"Titulaires d’une licence, toutes nationalités. Tu postules directement au master choisi dans le catalogue.","en":"Bachelor’s graduates, any nationality. You apply directly to the master’s of your choice in the catalogue."},"deadline":"2027-01-31","deadlineNote":{"fr":"Chaque master fixe sa propre date, en général entre octobre et janvier. Ouvre le catalogue et note la date de chaque master qui t’intéresse.","en":"Each master’s sets its own date, usually between October and January. Open the catalogue and note the date of each master’s you like."},"lien":"https://www.eacea.ec.europa.eu/scholarships/erasmus-mundus-catalogue_en","source":"eacea.ec.europa.eu","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-ubc-scholars-2027', 'bourse', 'Programme des boursiers internationaux UBC 2027', 'University of British Columbia (Canada)', 'CA', null, 'sciences', 'Bourses selon le besoin et le mérite ; la bourse Vantage One peut couvrir tout le programme et la vie sur place', null, 'licence', '2026-11-15', 'Élèves qui entrent à l’université directement après le lycée (première licence), avec un fort besoin financier, de bonnes notes et un engagement. Une recommandation de ton lycée est demandée.', 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/international-scholars/', false, '{"id":"b-ubc-scholars-2027","type":"bourse","titre":"Programme des boursiers internationaux UBC 2027","organisation":"University of British Columbia (Canada)","pays":"CA","domaine":"sciences","domaines":["sciences","ingenierie","business","art","sante","tech","education","droit"],"niveau":"licence","niveaux":["licence"],"montant":{"fr":"Bourses selon le besoin et le mérite ; la bourse Vantage One peut couvrir tout le programme et la vie sur place","en":"Need- and merit-based awards; the Vantage One award can cover the full programme and living costs"},"eligibles":{"fr":"Élèves qui entrent à l’université directement après le lycée (première licence), avec un fort besoin financier, de bonnes notes et un engagement. Une recommandation de ton lycée est demandée.","en":"Students entering university straight from secondary school (first bachelor’s), with strong financial need, good grades and leadership. A school nomination is required."},"ouverture":"2026-10-05","deadline":"2026-11-15","deadlineNote":{"fr":"Dossier de bourse avant le 15 novembre 2026 ; les formulaires de ton lycée sont dus quelques jours avant.","en":"Scholarship application by 15 November 2026; your school’s forms are due a few days earlier."},"lien":"https://you.ubc.ca/financial-planning/scholarships-awards-international-students/international-scholars/","source":"you.ubc.ca","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-10-05', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-constructor-2027', 'bourse', 'Bourses Talent — Constructor University (rentrée 2027)', 'Constructor University, Brême (Allemagne)', 'DE', null, 'tech', 'Jusqu’à 100 % des frais de scolarité (la bourse JetBrains couvre aussi la vie sur place pour certaines licences en informatique)', null, 'licence', '2026-10-29', 'Avoir une offre d’admission et réussir l’examen de bourse.', 'https://constructor.university/scholarships', false, '{"id":"b-constructor-2027","type":"bourse","titre":"Bourses Talent — Constructor University (rentrée 2027)","organisation":"Constructor University, Brême (Allemagne)","pays":"DE","domaine":"tech","domaines":["tech","ingenierie","sciences","business"],"niveau":"licence","niveaux":["licence","master"],"montant":{"fr":"Jusqu’à 100 % des frais de scolarité (la bourse JetBrains couvre aussi la vie sur place pour certaines licences en informatique)","en":"Up to 100% of tuition (the JetBrains scholarship also covers living costs for some computer science bachelor’s)"},"eligibles":{"fr":"Avoir une offre d’admission et réussir l’examen de bourse.","en":"Hold an admission offer and pass the scholarship exam."},"deadline":"2026-10-29","deadlineNote":{"fr":"Examen de bourse au plus tard le 29 octobre 2026 à 14 h (UTC).","en":"Scholarship exam by 29 October 2026, 14:00 UTC."},"lien":"https://constructor.university/scholarships","source":"constructor.university","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
