ers-admissions","source":"mbzuai.ac.ae","verifie":"2026-10-10","premium":true}'::jsonb, '2026-10-10', '2026-10-10', '2026-09-07', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
